// 简体中文 stories: I18N["zh-CN"].stories["<civ id>:<activity>"] = "…" (same keys as cultures/stories/europe-northeast.js).
Object.assign(I18N["zh-CN"].stories, {
  // ——— Goths ———
  "goths:hunt": "想象：在维斯瓦河畔的橡树与松林之间，哥特猎人在晨光初露时出发，手持长矛，带着瘦削的猎犬，循着马鹿的蹄印穿过湿漉漉的蕨丛。弹里拉琴的人留在家中；在这荒野里，唯一的音乐是男人们之间互相应答的牛角号声。一头好雄鹿意味着长屋里有肉可吃，冬天有兽皮御寒；下刀之前，猎人们默默地向诸神致谢。",
  "goths:battle": "378年8月9日，在阿德里安堡（Ἁδριανούπολις）附近，弗里提格恩的哥特车阵在酷热中等候，瓦伦斯皇帝的罗马大军口渴疲惫地开到阵前。就在此时，阿拉塞乌斯和萨弗拉克斯率领的哥特骑兵征粮归来，如闪电般杀入战场。罗马军阵被挤压得密不透风，士兵连剑都举不起来。瓦伦斯战死，尸首始终未能找到。对当初作为饥饿难民渡过多瑙河的哥特人来说，这一天，他们不再乞求。",
  "goths:gather": "四世纪时，本身就是哥特人的主教乌尔菲拉（Ulfilas）为本族创制了文字，并把《圣经》译成哥特语。想象一群聚在多瑙河边的会众，那些从未见过自己语言写成文字的农夫和战士，第一次听到用母语朗读的主祷文：Atta unsar thu in himinam（𐌰𐍄𐍄𐌰 𐌿𐌽𐍃𐌰𐍂 𐌸𐌿 𐌹𐌽 𐌷𐌹𐌼𐌹𐌽𐌰𐌼）。如今收藏于乌普萨拉的《银圣经》（Codex Argenteus），仍以银色墨水在紫色羊皮纸上保存着他的译文。",
  "goths:ritual": "约370年，哥特审判官阿塔纳里克坚守古老的神祇。一尊木像被放在车上挨家挨户地拉过，每户人家都必须出门鞠躬献祭，祈求诸神在危难之时保全族人。基督徒哥特人萨巴（Σάβας）拒绝从命，372年被溺死在穆赛奥斯河（Μουσαῖος）中。双方都相信，哥特人的未来取决于他们敬奉的是谁，谁也没有把这个问题当作儿戏。",
  "goths:rain": "376年，被匈人驱赶西迁的数万哥特人聚集在多瑙河北岸，等待罗马允许他们渡河。几天拖成了几周。粮食吃光了；史家阿米亚努斯记载，罗马军官卖狗给他们充饥，一条狗换一个哥特孩子去当奴隶。他们望着对岸，望着天空，等待世界向他们敞开，而他们的耐心渐渐变成了怒火。",
  "goths:flood": "376年，瓦伦斯皇帝终于准许特尔文吉人渡过多瑙河时，河水正因雨涨满。阿米亚努斯·马塞利努斯写道，哥特人日夜不停地渡河，有的乘船，有的坐筏，有的趴在掏空的树干上；许多人想逆着湍急的水流游过去，结果被冲走淹死。对岸的家人看着船只靠岸，一个个清点人头，心里明白有些人永远到不了了。",
  "goths:wind": "250年代和260年代，哥特人和赫鲁利人的战团乘轻舟驶入黑海，劫掠了特拉布宗（Τραπεζοῦς）、博斯普鲁斯（Βόσπορος），甚至雅典（Ἀθῆναι）。佐西莫斯（Ζώσιμος）记载，有些船队遭遇风暴而四散。想象那些水手紧抓船舷，黑色的浪头砸在身上，远离任何熟悉的海岸，直到风停之前，能依靠的只有手中的桨和诸神。",
  "goths:fire": "410年8月24日，阿拉里克率领的西哥特人从萨拉里亚门（Porta Salaria）进入罗马，这是八百年来第一支攻入城内的外族军队。城门附近的建筑燃起大火，其中包括史家撒路斯提乌斯（Sallustius）的宅邸和花园。身为基督徒的阿拉里克下令保全彼得和保罗的教堂，作为避难所。整整三天，长期被当作难民和雇佣兵的哥特人，占据了这座曾经鄙视他们的城市。",
  "goths:thunder": "想象：在大多数哥特人皈依基督教之前，雷霆属于天神图纳兹（Thunraz），他挥舞铁锤击打巨人。夏日的风暴滚过黑海草原上的一座哥特村庄，妇女们把孩子拉进屋里，老人们站在门口，看着闪电在草原上行走，从它的方向判断这一年是会带来战争，还是好收成。",
  "goths:birth": "史家约达尼斯记载，约454年，就在东哥特国王瓦拉米尔击退一队匈人的当天，一名信使骑马奔向他的弟弟提乌迪米尔，报告其侧室埃蕾留娃生下了一个儿子。这个男孩就是后来被称为大帝的狄奥多里克，他将统治意大利三十年。摇篮边的人谁也不知道这些；他们只看到同一天里的一场胜利和一个新生命，盼望这是个吉兆。",
  "goths:death": "410年，攻下罗马仅数月后，阿拉里克在卡拉布里亚突然去世。约达尼斯写道，他的哥特人让布森托河改道，在河床上挖墓，将国王连同大批财宝葬在那里，然后让河水重新流回，盖住他的坟墓。挖墓的俘虏全被杀死，好让无人能找到那个地方。河水至今仍从墓上流过，也确实从来没有人找到过。",
  // ——— Teutons (Teutonic Order) ———
  "teutons:hunt": "普鲁士的条顿骑士以驯鹰闻名。他们在波罗的海沿岸直到利沃尼亚一带捕捉矛隼和游隼，在马林堡训练，每年作为外交礼物送给欧洲各地的国王和诸侯。想象一位身披黑十字白斗篷的骑士修士，手套上停着一只戴头罩的猎鹰，骑马驰过冰封的沼泽，而这只不久将在巴黎或伦敦为骑士团赢得友谊的鸟儿，正在学习俯冲扑击苍鹭。",
  "teutons:battle": "1410年7月15日，在格伦瓦尔德（坦嫩贝格），大团长乌尔里希·冯·容金根派人给国王雅盖沃和大公维陶塔斯送去两把出鞘的剑，嘲笑他们迟迟不战。波兰—立陶宛联军应战，到傍晚，骑士团大军已被击溃。乌尔里希本人在冲锋中阵亡，骑士团大多数高级修士也一同战死。骑士们来到普鲁士时深信上帝与他们同行；那天夜里，许多幸存者都在想，自己究竟做了什么，竟失去了祂的眷顾。",
  "teutons:gather": "十四世纪后期，骑士团为来自英格兰、法兰西和帝国各地前往普鲁士的客座十字军设立了「荣誉之桌」（Ehrentisch）。在出征立陶宛之前，最有功勋的骑士们在旗帜下入席赴宴，传令官高声宣读他们的事迹，每人获赠一枚刻有格言「荣誉战胜一切」（Honneur vainc tout）的徽章。诗人乔叟说，他笔下的骑士就曾坐在那张桌旁：ful ofte tyme he hadde the bord bigonne in Pruce。",
  "teutons:ritual": "大团长去世后，修士们聚集在马林堡的会堂里推选继任者。他们选出十三名选举人，象征基督和十二使徒；选举人在弥撒之后、向骑士团的主保圣母玛利亚祈祷完毕才投票。骑士们相信，这一选择实际上并不出于他们自己，而是出于上帝；他们静静等候钟声响起，宣告上天赐给他们的领袖是谁。",
  "teutons:rain": "骑士团对立陶宛的远征（Reisen）全看天气。冬季远征需要严寒，让马匹和车辆能越过沼泽与河流；夏季远征则需要干燥的地面。若解冻来得太早，或秋雨把道路泡成泥沼，来自欧洲各地的客座骑士就只能在柯尼斯堡一待数周，饮酒掷骰，仰望天空，等待大地封冻，好让他们的十字军开拔。",
  "teutons:flood": "骑士团修筑堤坝、开挖排水渠，并招来荷兰和德意志移民，把维斯瓦河（Wisła）三角洲的沼泽地——茹瓦维（Żuławy）——变成了农田。每年春天，维斯瓦河和诺加特河都因融雪和冰凌而上涨，村民们拿着铁锹和沙袋，日夜在堤上巡守。一旦决堤，河水便涌过几代人辛苦开垦的田地，骑士团的修士们会骑马赶去帮忙堵住缺口。",
  "teutons:wind": "想象：深秋，一场大风从波罗的海刮上库尔斯沙嘴（Kuršių nerija）。一艘满载盐和布匹、还搭着两名年轻客座骑士驶往梅默尔的柯克船，被狂风沿着狭长的沙坝一路驱赶，船帆被撕走。船员们向圣母祈祷，把货物抛入海中。到了早晨，船已在海滩上撞得粉碎，骑士团治下海岸的渔民们把幸存者从浪里拖上岸，用印着黑十字的斗篷裹住他们。",
  "teutons:fire": "1410年格伦瓦尔德之战后，波兰—立陶宛联军向马林堡进军。只是一名普通指挥官的海因里希·冯·普劳恩挺身主持防务，下令焚毁城堡下方的市镇，不让敌军在那里找到藏身之处。骑士团自己的子民眼看着自家房屋陷入火海。城堡坚守了八个星期的围攻，海因里希因保全了骑士团的心脏，被推选为大团长以示感谢。",
  "teutons:thunder": "想象：在一座新近被征服的普鲁士村庄里，老人们仍记得雷神佩尔库纳斯的神圣橡树，那些树已被骑士们砍倒。一个夏日傍晚，风暴骤起，闪电劈开了教堂的钟楼。德意志神父敲钟祈祷；普鲁士老祖母们则低声嘀咕，说古老的神并没有忘记。两边的人都害怕，也都在聆听同一声雷鸣。",
  "teutons:birth": "想象：骑士们是立誓独身的修士，但他们统治的土地上住满了依库尔姆法定居的移民。在托伦附近的一座新村里，一位农妇彻夜分娩，邻居们为圣母点起一支蜡烛。接生婆把一个健康的男婴托到灯光下。父亲盼着他将来继承田地；母亲则盼着他永远不必骑马随远征队去立陶宛。",
  "teutons:death": "条顿骑士团的历任大团长都葬在马林堡城堡教堂下方的圣安妮礼拜堂，墓上覆盖着刻有名字的石板。格伦瓦尔德之战后，国王雅盖沃以礼送还乌尔里希·冯·容金根的遗体，他被安葬在那里，与前任们长眠在一起。修士们用拉丁语吟唱亡者日课，这是一首庄严低沉的圣咏，献给一位他们相信作为基督的战士而死去的骑士。",
  // ——— Germans ———
  "germans:hunt": "11月3日是圣胡贝图斯节（Hubertustag），德国猎人在这天举行胡贝图斯狩猎（Hubertusjagd）。传说胡贝图斯原是个鲁莽的猎人，他看见一头雄鹿的双角之间闪耀着十字架，从此归向上帝。所以狩猎以一场胡贝图斯弥撒和猎号的铜管声开始，以「猎获陈列」（Strecke）结束：猎物一排排摆在冷杉枝上，每只嘴里放一根小枝作为「最后一口」，猎号为每一头被猎获的动物吹响致敬的号声。",
  "germans:battle": "1525年2月24日，在帕维亚，被称为「雇佣兵之父」的格奥尔格·冯·弗伦茨贝格率领德意志雇佣步兵（Landsknechte），为查理五世皇帝迎战法国国王弗朗索瓦一世（François Ier）。身穿开衩蓬袖服装的长矛手，伴着战鼓和横笛，在晨雾中冲破了园林的围墙。到中午，法军已经溃败，法国国王沦为俘虏。弗伦茨贝格的士兵们已经几个月没领到军饷，却为这场胜利传唱了许多年。",
  "germans:gather": "1810年10月12日，巴伐利亚王储路德维希迎娶萨克森-希尔德堡豪森（Sachsen-Hildburghausen）的特蕾莎公主，慕尼黑（München）市民受邀来到城门外的一片草地，观看为庆贺婚礼而举行的赛马。这片草地被命名为特蕾莎草地（Theresienwiese），庆典第二年又办了一次，第三年也是如此。慕尼黑啤酒节就从那场婚礼发展而来：铜管乐队、长桌、帐篷，整座城市聚在一起饮酒歌唱。",
  "germans:ritual": "1521年4月17日傍晚，马丁·路德在沃尔姆斯帝国议会（Reichstag zu Worms）上站在查理五世皇帝面前，被要求收回自己的著作。他请求给他一夜时间考虑。按传统说法，他整夜都在祈祷，深知自己的回答可能意味着火刑柱。第二天，他说自己的良心受上帝之道约束，不能违背。那句著名的「这是我的立场」（Hier stehe ich）很可能是后人添加的；那一夜的祈祷却是真实的。",
  "germans:rain": "1816年是「无夏之年」。印度尼西亚坦博拉火山的喷发让火山灰布满天空，德国几乎下了一整年的雨。谷物烂在田里，马匹因缺少燕麦而饿死，人们一周又一周地望着灰色的云层，等待一个始终没有出现的太阳。在曼海姆，卡尔·德莱斯造出了一种两轮的「跑步机」，也就是自行车的前身，部分原因正是为了替代死去的马匹。",
  "germans:flood": "1962年2月16日至17日夜间，一场北海风暴潮冲垮了汉堡的堤坝。人们还在熟睡时，海水便灌进了威廉斯堡的低洼城区；315人遇难。年轻的警务参议员赫尔穆特·施密特越权调来联邦国防军和北约直升机，把一家家人从屋顶上救下。汉堡人至今仍记得那份寒冷与黑暗，也记得那些划船穿过街道去救陌生人的邻居。",
  "germans:wind": "1362年1月16日，一场来自西南的大风暴驱赶北海海水漫过弗里西亚和石勒苏益格的海岸。这场「大溺亡」（Grote Mandrenke）夺去了数万人的生命，吞没了商镇伦霍尔特，使它消失在瓦登海（Wattenmeer）之下。后来渔民们说，在宁静的夜晚能听见它教堂的钟声在水下回响，这个传说让人们对那场风暴的记忆延续了几个世纪。",
  "germans:fire": "1842年5月5日，汉堡德希街（Deichstraße）上一位雪茄匠的房子起火。干燥的风让火势蔓延了四天；老城被焚毁，圣尼古拉教堂（St. Nikolai）和圣彼得教堂（St. Petri）倒塌，市政厅也被炸掉以阻止火势。约两万人失去了家园。汉堡重建时修了现代化的下水道系统和宽阔的街道，但亲眼看着城市燃烧的人们，永远忘不了那片通红的天空。",
  "germans:thunder": "1505年7月2日，法律系学生马丁·路德步行返回埃尔福特，在施托特恩海姆村附近遇上了雷雨。一道闪电落在近旁，把他掀翻在地。惊恐之中他喊道：「救救我，圣安妮，我要去当修士！」（Hilf du, Sankt Anna, ich will ein Mönch werden!）两周后，他违背父亲的意愿，进入了埃尔福特的奥古斯丁会修道院。田野里的一场风暴，改变了基督教的历史。",
  "germans:birth": "1483年11月10日，艾斯莱本一个矿工家庭的汉斯和玛格丽特·卢德夫妇生下一个儿子。第二天正逢圣马丁节，他们把孩子抱到圣彼得和保罗教堂受洗，按当天的圣人为他取名马丁。婴儿夭折十分常见，洗礼一刻也不能耽搁。父亲希望这孩子将来当律师，光耀门楣；谁也想不到他日后真正做了什么。",
  "germans:death": "十六、十七世纪的德国新教徒会为中产和贵族家庭的逝者印制《葬礼布道文》（Leichenpredigten）。每本小册子收录墓前宣讲的布道词、逝者生平、病情与临终遗言，以及亲友所作的诗；留存至今的约有二十五万册。家人们朗读这些册子以求慰藉；今天，它们是了解普通德国人如何生活、如何相爱、如何怀着复活的希望面对死亡的最佳史料之一。",
  // ——— Holy Roman Empire ———
  "holy-roman-empire:hunt": "被誉为「世界奇迹」（Stupor Mundi）的腓特烈二世皇帝（Friedrich II.）约在1240年写成一部关于鹰猎的巨著《论以鸟狩猎的技艺》（De arte venandi cum avibus）。他亲自观察猎鹰数十年，测量它们的翅膀，当观察证明亚里士多德有误时，他敢于纠正这位先哲。想象这位皇帝从他在阿普利亚（Puglia）的城堡策马而出，拳上立着一只矛隼，看着鸟儿迎风攀升，一边思索飞行的道理——半是猎人，半是科学家。",
  "holy-roman-empire:battle": "955年8月10日，在奥格斯堡附近的莱希费尔德，国王奥托一世迎战已劫掠德意志土地五十年的匈牙利骑射手。他手持圣枪（Heilige Lanze），据信枪中嵌有一枚十字架上的钉子；战前全军彼此立誓和睦。匈牙利人大败，首领被处以绞刑。奥托在战场上被将士们拥呼为皇帝，七年后在罗马加冕。",
  "holy-roman-empire:gather": "936年8月7日，王国的贵族们聚集在亚琛查理曼（Karl der Große）的礼拜堂，观看奥托一世加冕。他接受傅油，佩上宝剑，被引至楼廊上查理曼的大理石宝座，让所有人都能看见他。随后的宴会上，洛林（Lothringen）、法兰克尼亚（Franken）、施瓦本（Schwaben）和巴伐利亚（Bayern）四位公爵分别担任他的宫廷总管、膳食总管、司酒官和司马官。整个王国在同一座大厅里，围绕着同一个人聚在一起。",
  "holy-roman-empire:ritual": "莱茵河（Rhein）畔的女修道院院长宾根的希尔德加德（Hildegard von Bingen）自幼便见异象，她把这些异象记录在1151年完成的《认识主道》（Scivias）一书中。历任教宗、主教以及腓特烈·巴巴罗萨皇帝（Friedrich Barbarossa）都曾写信向她请教未来之事。她曾严厉警告皇帝不要支持对立教宗。在她的修道院里，修女们吟唱着她亲自创作的圣咏，相信上帝正借她之口，讲述教会与帝国将要面临的命运。",
  "holy-roman-empire:rain": "1077年1月，被教宗格里高利七世开除教籍的亨利四世皇帝（Heinrich IV.）在隆冬翻越阿尔卑斯山，来到卡诺莎城堡。整整三天，他身穿悔罪者的粗羊毛衫，赤脚站在城门外的雪地里，等候教宗接见。城堡里，格里高利也在等待，权衡着决定。第四天，城门打开了。在德语里，「去卡诺莎」（Gang nach Canossa）至今仍意味着低头认错，等待对方回心转意。",
  "holy-roman-empire:flood": "1342年7月，连日暴雨之后，「抹大拉的玛利亚洪水」（Magdalenenhochwasser）袭击了帝国的腹地。美因河、莱茵河（Rhein）、多瑙河（Donau）、摩泽尔河（Mosel）和易北河全部决堤；在法兰克福，洪水漫到了大教堂；在维尔茨堡，桥梁被冲毁；在科隆（Köln），船只直接划过了城墙。整个中欧山坡上的表土被冲刷殆尽。那年夏天留在古老墙壁上的洪水标记至今仍清晰可见，此后再没有哪次洪水超过它。",
  "holy-roman-empire:wind": "1184年圣灵降临节，腓特烈·巴巴罗萨皇帝（Friedrich Barbarossa）在美因茨举行盛大的宫廷庆典，为他的儿子们授封骑士，数以万计的宾客在莱茵河畔的草地上搭起一座帐篷城。随后，一场猛烈的风暴席卷营地。一座新建的木教堂和几栋房屋倒塌，压死了不少人。编年史家认为这是上天对骄傲的警示，这场本想彰显帝国荣耀的庆典，最终在悲痛中收场。",
  "holy-roman-empire:fire": "1689年，普法尔茨继承战争期间，法军焚烧了施派尔及其大教堂——萨利安王朝历代皇帝的安葬之所。士兵们撬开皇帝的陵墓搜寻财宝，把从康拉德二世（Konrad II.）到亨利五世（Heinrich V.）的历代皇帝遗骨抛撒一地。被逐出城的施派尔居民站在田野里，眼看着宏伟的罗马式中殿燃烧。帝国连自家皇帝的坟墓都保护不了。",
  "holy-roman-empire:thunder": "在中世纪帝国各地，每当雷雨将至，教堂司事便登上钟楼敲钟。人们相信这种「驱雷钟」（Wetterläuten）能驱散风暴和冰雹，因为教堂的钟都经过祝圣，许多钟上还刻着 fulgura frango——「我击碎闪电」——之类的铭文。有时闪电反而劈中钟楼，夺去敲钟人的性命。可村民们照样敲钟，他们站在自己的庄稼和天空之间，手中只有祈祷与青铜。",
  "holy-roman-empire:birth": "1194年12月26日，四十岁、婚后多年无子的康斯坦丝皇后（Costanza）在意大利的耶西生下一个儿子。由于许多人怀疑这个年纪的女人是否真能成为孩子的生母，她让人在集市广场上搭起帐篷，当着城中主妇们的面分娩，随后又公开给婴儿哺乳。这个男孩就是腓特烈二世（Friedrich II.），他长大后令整个基督教世界惊叹、不安，乃至愤怒。",
  "holy-roman-empire:death": "1190年6月10日，第三次十字军东征途中，腓特烈·巴巴罗萨皇帝（Friedrich Barbarossa）在渡过安纳托利亚的萨勒夫河时溺亡。惊愕的军队将他的遗体煮过以便保存：他的肉身葬在安条克（Ἀντιόχεια），骨骸本要运往耶路撒冷，却在途中遗失。正因为没有一座坟墓安葬他，德国人便传说他并没有死，而是在基弗豪塞山中沉睡，红胡子穿过石桌生长，等待帝国需要他时归来。",
  // ——— Order of the Dragon ———
  "order-of-the-dragon:hunt": "想象：在南喀尔巴阡山（Carpații Meridionali）的山毛榉林中，一位佩戴龙骑士团徽章——一条盘成圆环、背上有红十字的龙——的瓦拉几亚贵族，带着猎手们骑马追猎野猪。猎犬在山谷中狂吠，号角响起，野猪冲出藏身之处。狩猎是消遣，也是演练：在场的每个人都知道，奥斯曼的边境就在多瑙河的另一边。",
  "order-of-the-dragon:battle": "1462年6月17日夜，龙骑士之子弗拉德三世·德古拉（Drăculea）率领数千骑兵突袭驻扎在特尔戈维什泰附近的苏丹穆罕默德二世（محمد ثانی）大营，企图在帐中刺杀这位君士坦丁堡（Κωνσταντινούπολις）的征服者。黑暗中火把、号角和恐慌交织；突袭打错了营帐，穆罕默德幸免于难。几天后，奥斯曼大军在特尔戈维什泰城外看到了一片「穿刺之林」，心有余悸的苏丹率军回国。",
  "order-of-the-dragon:gather": "1408年12月12日，匈牙利国王西吉斯蒙德（Zsigmond）和王后采列的芭芭拉与二十四位贵族领主共同创立了龙骑士团（Societas Draconistarum）。他们宣誓保卫十字架、抵御奥斯曼人，并誓死效忠国王及其家族。成员们把龙形徽章佩戴在衣服上，也刻在自己的墓上。想象布达的大厅里旗帜飘扬、烛光闪烁，骑士们一个接一个跪下宣誓，双手放在国王的双手之间。",
  "order-of-the-dragon:ritual": "1431年2月，在纽伦堡（Nürnberg），西吉斯蒙德皇帝授予流亡中的瓦拉几亚王子弗拉德龙骑士的封号。从此他被称为弗拉德·德拉库尔，即「龙公弗拉德」。仪式在神职人员面前举行，有弥撒，也有手按福音书立下的誓言。弗拉德祈求上帝让他夺回父亲的王位，赐他守住多瑙河的力量；不到五年，他便统治了瓦拉几亚（Țara Românească）。",
  "order-of-the-dragon:rain": "1462年后，弗拉德三世·德古拉（Drăculea）被匈牙利国王马蒂亚斯·科尔维努斯（Hunyadi Mátyás）羁押了约十二年，先在维谢格拉德，后在佩斯。这位曾令人闻风丧胆的瓦拉几亚大公，一季又一季地等待着，眼看敌人统治他的国土，奥斯曼人日益强大。传说他在囚室里捉老鼠，把它们穿在小棍上。1474年他终于获释，1476年最后一次策马回乡，夺回了王位。",
  "order-of-the-dragon:flood": "想象：喀尔巴阡山的春季融雪让阿尔杰什河和多瑙河（Dunărea）暴涨，河面在瓦拉几亚平原上铺开数英里宽。一座由骑士团盟友驻守的边境要塞，河水已经拍打着城门，守军望着对岸。他们说不清该不该感激：淹没他们田地的洪水，也把奥斯曼劫掠者挡在了对岸——至少在水退之前是这样。",
  "order-of-the-dragon:wind": "想象：一场秋季风暴呼啸着穿过特兰西瓦尼亚（Ardeal）与瓦拉几亚之间的布兰山口。一小队骑手携带着骑士团致特尔戈维什泰大公的信件，躲在一处岩檐下，暴雨抽打着悬崖，林中的松树咔嚓断裂。队长抚摸着斗篷上的龙形徽章，低声向屠龙者圣乔治祈祷——他们所佩戴的，恰是圣乔治徽记的反面。",
  "order-of-the-dragon:fire": "1461至1462年冬，弗拉德三世越过冰封的多瑙河（Dunărea），沿河从齐姆尼恰一直烧到黑海，焚毁了奥斯曼的堡垒、城镇和村庄。在1462年2月11日致马蒂亚斯国王的信中，他逐地列出了死者人数，总计两万余人。对基督教诸侯来说，这证明了他绝不屈服；对多瑙河沿岸的百姓来说，那是一个充满浓烟、灰烬与恐惧的冬天。",
  "order-of-the-dragon:thunder": "想象：雷声滚过波埃纳里城堡的城墙——这座由弗拉德三世重建的要塞，矗立在阿尔杰什河上方的悬崖上。胸墙上的卫兵看着闪电劈中对面的山峰，在胸前画十字。下方的礼拜堂里，神父正在吟唱晚祷，老兵们说，上帝用雷声提醒诸侯：即使最坚固的城堡，在苍穹之下也渺小得很。",
  "order-of-the-dragon:birth": "约1431年，在特兰西瓦尼亚（Ardeal）山城锡吉什瓦拉，流亡的瓦拉几亚王子弗拉德——他在同一年加入了龙骑士团——得了第二个儿子。相传他出生的那座位于城镇广场上的房子至今仍在。这个孩子就是弗拉德三世，后来被称为德古拉（Drăculea），意为「龙之子」。父亲希望他能夺回瓦拉几亚；谁也无法预见他将留下怎样的黑暗传说。",
  "order-of-the-dragon:death": "1476年到1477年之交，弗拉德三世在布加勒斯特（București）附近与奥斯曼人作战时阵亡，也许是遭到了自己手下贵族的背叛。他的首级被送往君士坦丁堡示众为证。相传他的遗体由斯纳戈夫修道院的修士们安葬在湖中的一座小岛上，但墓地始终未能确认。对他的人民来说，他既是恐怖的化身，也是守护者，他们也以这两种身份哀悼他。",
  // ——— Vikings ———
  "vikings:hunt": "约890年，一位名叫奥特雷（Óttarr）的挪威首领拜访了威塞克斯（Westseaxe）的阿尔弗雷德国王（Ælfrēd），向他讲述自己在遥远北方的家乡哈洛加兰。他说自己曾绕过北角（Nordkapp）去猎捕海象——他称之为「马鲸」——为的是它们优质象牙般的长牙，以及可以割成船缆的兽皮。他夸口说自己和另外五人两天里就杀了六十头。阿尔弗雷德的书记官把这些记录下来，他的声音因而以古英语保存至今。",
  "vikings:battle": "1066年9月25日，在斯坦福桥，挪威国王「无情者」哈拉尔（Haraldr harðráði）遭到哈罗德·戈德温森（Harold Godwines sunu）率领的英格兰军队突袭。北欧人把锁子甲都留在了船上。编年史记载，一名高大的北欧战士手持战斧独自守住桥头，砍倒了四十人，直到一个英格兰人坐在木桶里漂到桥下，从下方用长矛刺中了他。哈拉尔喉咙中箭倒下，至死都在战斗，正如一位国王应有的样子。",
  "vikings:gather": "约930年，冰岛的定居者们在辛格韦德利（Þingvellir）——一道夹在峭壁间的裂谷——创立了露天议会阿尔庭（Alþingi）。每年六月，首领和农民们从全岛各地骑马赶来，在草皮棚屋里扎营两周。法律宣讲人（lögsögumaður）站在法律石（Lögberg）上，每年凭记忆背诵三分之一的法律。人们在这里裁决纠纷、商定婚事、交换消息，一座没有国王的岛屿就这样自己治理自己。",
  "vikings:ritual": "《红发埃里克萨迦》（Eiríks saga rauða）讲述了约1000年格陵兰（Grænland）的一个饥荒之冬。在赫约尔夫斯内斯（Herjólfsnes），农民们请来了女先知（völva）索尔比约格（Þorbjörg）。她身披蓝色斗篷，头戴黑羔羊皮兜帽，帽里衬着白猫皮，坐在高座上。年轻女子古德丽德（Guðríður）为她唱起古老的护咒之歌，精灵们纷纷聚拢。随后索尔比约格预言饥荒将随春天结束，还预言古德丽德将在远方迎来非凡的命运。",
  "vikings:rain": "想象：在挪威一处峡湾的出口，一艘准备向西驶往冰岛（Ísland）的船上，船员们在等待顺风（byr）。一天天的雨和逆风过去了。船上载满了牛、种粮和一家家人；船长观察云和鸟，老人们解读海浪的涌动。没有人逆着大海航行。当风终于转向东方，他们不到一个小时便解缆出发，把故土留在身后。",
  "vikings:flood": "想象：在冰岛南部，米达尔斯冰川（Mýrdalsjökull）之下藏着卡特拉火山。某一天大地震动，一场冰川洪水（jökulhlaup）冲过冲积平原，融水、冰块和黑沙汇成一堵墙。平原上的农民只有几分钟时间把牛群赶到高处。洪水过后，原先农庄所在的地方成了一片灰色的荒原，人们又从头开始，就像冰岛人一向所做的那样。",
  "vikings:wind": "据《格陵兰人萨迦》（Grænlendinga saga）记载，986年，比亚德尼·赫尔约尔夫松从冰岛（Ísland）启航，前往格陵兰（Grænland）与父亲团聚。一场大风暴和浓雾让他的船偏离航线多日。天放晴后，船员们看到一片长满树林、丘陵低矮的陆地，根本不是格陵兰。比亚德尼拒绝登陆，转而向北航行。他成了第一个看见美洲的欧洲人，而他的手下却抱怨他连岸都没上。",
  "vikings:fire": "《尼亚尔萨迦》记载，约1011年，弗洛西率领一伙仇敌包围了尼亚尔在冰岛贝里索斯赫沃尔（Bergþórshvoll）的农庄，并放火焚烧。弗洛西让尼亚尔的妻子贝格索拉（Bergþóra）离开。她拒绝了：「我年轻时嫁给尼亚尔，曾向他许诺，我们俩要同一命运。」这对老夫妻躺到床上，把小孙子放在两人中间，盖上一张牛皮，房屋在他们身上燃烧倒塌。",
  "vikings:thunder": "《红发埃里克萨迦》（Eiríks saga rauða）记载，在文兰（Vínland）的一个饥荒之冬，老猎人索尔哈尔（Þórhallr）失踪了。人们发现他在一处山崖上，仰望天空，喃喃自语。不久之后，一头鲸鱼被冲上岸，索尔哈尔说：「红胡子不是比你们的基督更强吗？这是我为索尔（Þórr）作诗得到的报酬。」许多北欧人即使受洗之后，仍佩戴小小的雷神之锤（Mjölnir）作为护身符。",
  "vikings:birth": "在北欧世界，新生儿会先被放在地上，直到父亲决定是否抚养。如果父亲把孩子抱起，孩子便要洒水（ausa vatni）并获得名字，往往取自一位已故亲人的名字，希望他的好运能在孩子身上重现。从那一刻起，孩子就属于这个家族了。每个家庭都希望男孩将来能成为伟大的吟游诗人（skald）或首领，同时也害怕命运女神诺伦（Nornir）早已纺定的命运。",
  "vikings:death": "961年，「善良者」哈康国王在菲蒂亚尔之战中阵亡，他为保卫挪威抵御「血斧」埃里克（Eiríkr blóðøx）的儿子们而战死。吟游诗人埃温德（Eyvindr）创作了《哈康之歌》（Hákonarmál）：女武神贡杜尔和斯科古尔驰过战场，选中哈康，引领他前往瓦尔哈拉（Valhöll），奥丁（Óðinn）的英雄们在那里欢迎他。他的部下悲痛不已，但他们也在歌唱。对北欧人而言，手握利剑而死的国王并没有失败；只要诗歌流传，他的名字就会长存。",
  // ——— Swedes ———
  "swedes:hunt": "每年秋天十月初，瑞典的驼鹿狩猎（älgjakt）拉开序幕。在北方的森林里，整村的人都加入狩猎队（jaktlag）：有人守在兽道口，有人带着吠叫的猎鹿犬穿行于云杉林和沼泽之间。北方的学校长久以来都会放「驼鹿假」。公鹿倒下后，猎人们围着篝火喝咖啡，鹿肉则分给每户人家，够吃一整个冬天。",
  "swedes:battle": "1632年11月6日，在萨克森（Sachsen）的吕岑，古斯塔夫二世·阿道夫国王（Gustav II Adolf）率领骑兵冲入浓雾，迎战华伦斯坦的帝国军队。他一马当先，消失在雾中；身中数弹，从马上跌落，孤独地死去。他那匹无人骑乘、浑身是血的战马跑回了瑞典阵线。怒不可遏的军队继续奋战，到夜幕降临时赢得了战场。瑞典赢了这场战役，却失去了「北方雄狮」（Lejonet från Norden）。",
  "swedes:gather": "仲夏节（midsommar）在最接近夏至的那个星期五，瑞典人聚集在全国各地的草地上。他们用桦树叶和鲜花装饰一根高高的仲夏柱（midsommarstång），一起把它竖起来，伴着提琴声围着它跳舞，跟着歌曲《小青蛙》（Små grodorna）像小青蛙一样蹦跳。随后是鲱鱼、新土豆、草莓和烈酒。在北方，太阳几乎不落，整个国家仿佛都彻夜不眠，庆祝光明。",
  "swedes:ritual": "1630年6月26日，古斯塔夫二世·阿道夫国王（Gustav II Adolf）率军在乌泽多姆岛的佩内明德登陆，加入三十年战争（trettioåriga kriget）。据当时的记载，他一踏上岸，便当着军官们的面跪在沙滩上，高声祈求上帝保佑这次出征。看到军官们落泪，他对他们说：祈祷得越多，仗就打得越好。接下来的这场战争，将决定新教德意志的未来。",
  "swedes:rain": "1867年，瑞典的春夏又冷又湿，霜冻和雨水毁掉了收成，1868年又遭逢干旱。斯莫兰和韦姆兰的家庭靠树皮面包度日，仰望天空，等待一个始终没有到来的丰年。后来，他们不再等了。在随后的几十年里，一百多万瑞典人移民美国；威廉·莫贝里的小说《移民》（Utvandrarna）讲述的，正是那些明白「自己不改变，世界就不会改变」的农民。",
  "swedes:flood": "想象：五月，春汛（vårflod）沿着诺尔兰的大河奔流而下。融雪让翁厄曼河的水位上涨数米，放排工（flottare）乘着木材从森林顺流漂向海岸边的锯木厂。木材在一处急流卡住了；河水回涌，漫进河边的村庄。男人们拿着长篙走上浮动的原木去撬开堵塞，他们的家人在岸上祈祷。",
  "swedes:wind": "1700年11月30日，十八岁的卡尔十二世国王（Karl XII）向围攻纳尔瓦、兵力四倍于己的俄军发起进攻。就在进攻的那一刻，暴风雪骤起，雪花迎面扑向俄军。瑞典人借着暴风雪的掩护分两路纵队推进，突破了堑壕。俄军全线崩溃。瑞典人相信这阵风是上帝派来的；彼得大帝（Пётр Великий）则从这场败仗中吸取教训，重建了他的军队。",
  "swedes:fire": "1697年5月7日，斯德哥尔摩的古老王宫三王冠宫（Tre Kronor）起火，当时卡尔十一世国王（Karl XI）的遗体正停放在宫内供人瞻仰。廷臣们穿过浓烟把国王的灵柩抬了出来，档案、藏书和珍宝则付之一炬。十四岁的卡尔十二世（Karl XII）眼看着童年的家消失。如今的斯德哥尔摩王宫（Stockholms slott）就建在原址上，但瑞典许多中世纪的档案在那一夜永远失传了。",
  "swedes:thunder": "在瑞典民间信仰中，雷声是托尔（Tor）驾着山羊拉的战车驶过天空，后来又被看作上帝在惩治巨魔和恶灵。农民在田里挖到石器时代的石斧，称之为「雷楔」（åskviggar），相信那是闪电留在地里的。他们把这些石斧藏在墙里或门槛下，保护房屋免遭火灾。夏日风暴来临时，一家人便静静坐着，等它过去。",
  "swedes:birth": "1626年12月，玛丽亚·埃莉奥诺拉王后在斯德哥尔摩城堡分娩。婴儿浑身是毛、哭声响亮，接生婆们起初宣布是个男孩。真相大白后，谁也不敢告诉国王，最后还是他的异母姐姐说了。据说古斯塔夫二世·阿道夫（Gustav II Adolf）大笑道：「她将来一定聪明，因为她把我们都骗了。」这个女孩就是克里斯蒂娜（Kristina），她六岁即位，后来亲政、退位，令整个欧洲为之惊叹。",
  "swedes:death": "1718年11月30日，卡尔十二世国王（Karl XII）在挪威围攻腓特烈斯滕要塞时视察战壕，被一枪击穿头部。士兵们用担架抬着他的遗体翻越积雪的群山，回到乌德瓦拉，再一路运往斯德哥尔摩，葬于骑士岛教堂（Riddarholmskyrkan）。古斯塔夫·塞德斯特伦的画作《运送卡尔十二世遗体回国》（Karl XII:s likfärd）描绘了雪中那支凄冷的队伍；至于是谁开的那一枪，瑞典人至今仍在争论。",
  // ——— Lithuanians ———
  "lithuanians:hunt": "1409年冬，为准备与条顿骑士团开战，国王约盖拉和大公维陶塔斯在比亚沃维耶扎原始森林举行了一场大狩猎。一连数周，猎人们猎杀欧洲野牛、原牛、驼鹿和鹿，把肉腌制后装桶，顺纳雷夫河和维斯瓦河（Wisła）漂运下去，供给军队。这是一场为战争而进行的狩猎。次年七月，这支军队在格伦瓦尔德（Žalgiris）投入了战斗。",
  "lithuanians:battle": "1236年9月22日，在绍伦附近，萨莫吉希亚和瑟米加利亚的战士截住了刚劫掠归来的利沃尼亚宝剑骑士团（Fratres militiae Christi Livoniae）。骑士们身披重甲，泥泞的沼泽地让他们的马匹寸步难行。轻装的立陶宛人从四面八方发起攻击。骑士团团长福尔克温和大部分骑士被杀，骑士团元气大伤，不得不并入条顿骑士团。立陶宛至今仍纪念这一天。",
  "lithuanians:gather": "立陶宛妇女在一起打麻、织布或收割时，会唱一种轮唱歌曲「苏塔尔蒂内」（sutartinės）。两三组人唱着彼此交叠的短句，让相邻的音刻意以二度音程碰撞，听起来像钟声，又像蜂鸣。歌词简单而古老：芸香、天鹅、亚麻布。这些歌属于劳作，也属于相聚；没有别人，一个歌者根本唱不成这种音乐。",
  "lithuanians:ritual": "立陶宛是欧洲最后一个异教国家，直到1387年才受洗。中世纪编年史记载，在维尔纽斯，如今大教堂所在的山谷里，曾有一团为诸神长明不灭的圣火。祭司们看守圣火，并抽签向诸神询问战事和收成；若是凶兆，大公便不会出兵。考古学家在大教堂地板下发现了一座祭坛，那正是新旧信仰交汇之处。",
  "lithuanians:rain": "1989年8月23日，来自立陶宛、拉脱维亚和爱沙尼亚的约两百万人手拉手，组成一条长达675公里的人链，从维尔纽斯经里加（Rīga）一直延伸到塔林。他们称之为「波罗的海之路」（Baltijos kelias）。那一天，距《莫洛托夫—里宾特洛甫条约》把他们交给斯大林（Сталин）已过去了五十年。他们等待世界改变，等了半个世纪；那天傍晚，他们站在路边歌唱。七个月后，立陶宛宣布独立。",
  "lithuanians:flood": "想象：每年春天，在涅曼河三角洲，河水随着从东方而来的融雪和冰凌上涨，岛上的鲁斯内村被大水围困。人们把奶牛搬到阁楼上，乘船去教堂和商店。白鹳飞回被淹草地上方屋顶的巢里。鲁斯内的居民从不与春汛（potvynis）抗争；他们像等待一个季节那样等待它，知道洪水退去后会留下肥沃的土壤。",
  "lithuanians:wind": "库尔斯沙嘴（Kuršių nerija）是波罗的海与潟湖之间一条狭长的沙地，17、18世纪时那里的森林被砍伐殆尽。此后，风暴推动巨大的沙丘开始移动。在随后的几十年里，游移的沙丘把纳格利艾、卡尔韦契艾等渔村一个接一个地吞没，连同村里的教堂和坟墓都埋在了沙下。库尔斯渔民一次又一次地搬家，直到最终在沙丘上种下青草和松树。",
  "lithuanians:fire": "1336年，条顿骑士团围攻皮莱奈山堡。由马尔吉里斯公爵率领的守军看出已经守不住了。他们不愿投降后被强迫受洗或沦为奴隶，于是把财物投入熊熊大火，杀死家人，然后与他们一同自焚。骑士团的编年史家马尔堡的维甘德（Wigand von Marburg）怀着恐惧记下了这一幕。对立陶宛人来说，皮莱奈成了不惜一切代价、宁要自由不肯屈服的象征。",
  "lithuanians:thunder": "立陶宛雷神佩尔库纳斯挥动斧头，劈击藏在树木和石头里的魔鬼。橡树是献给他的圣树，被闪电劈中的橡树更是神圣。雷声滚滚时，人们说那是佩尔库纳斯驾着火焰战车驰过云端；为了让春天的第一声雷为一年带来祝福，农民们会在地上打滚，或用面包敲击墙壁。许多人至今仍把雷雨称为「佩尔库尼亚」（Perkūnija）。",
  "lithuanians:birth": "立陶宛人相信，孩子出生时，命运女神莱玛会来到摇篮边，决定孩子的命运：他的幸福、他的悲伤，以及他死亡的时辰。她说出的话无法更改。妇女们聚在一起举行命名宴（krikštynos），婴儿的第一次洗澡要在水里放上草药和硬币。人人都祝孩子好运，同时也知道莱玛早已开了口。",
  "lithuanians:death": "据波兰编年史家扬·德乌戈什记载，1382年大公凯斯图蒂斯遇害后，他的遗体在维尔纽斯按古老的异教方式火化：与他的战马、盔甲和兵器、猎犬和猎鹰一同焚烧，好让他在另一个世界里像生前一样骑马狩猎。火焰在圣火山谷中升腾。立陶宛哀悼这位与条顿骑士团战斗了五十年的勇士。",
  // ——— Poles ———
  "poles:hunt": "1752年9月，国王奥古斯特三世（August III Sas）在比亚沃维耶扎森林举行了一场大狩猎。驱兽人把动物赶进围场，宫廷成员站在高台上射击；共有42头欧洲野牛（żubry）被杀，其中20头出自王后玛丽亚·约瑟法之手。一座记录战果的石方尖碑至今仍立在林中。两个世纪后，欧洲野牛几近灭绝，波兰人靠动物园里仅存的几头，重新把它繁育了回来。",
  "poles:battle": "1683年9月12日，国王扬三世·索别斯基率军解救被卡拉·穆斯塔法（قره مصطفی）的奥斯曼大军围困的维也纳（Wien）。傍晚时分，约一万八千名骑兵以翼骑兵（husaria）为先锋，从卡伦山的山坡上冲杀而下，这是历史上规模最大的骑兵冲锋。奥斯曼大营随之崩溃。索别斯基写信给教宗：Venimus, vidimus, Deus vicit——「我们来了，我们看见了，上帝征服了。」",
  "poles:gather": "收获结束时，波兰的村庄会举行丰收节（dożynki）。最后一捆谷物被编成花环，装点上鲜花、苹果和彩带，列队抬到教堂接受祝福，然后献给庄园主——如今则献给村长。接着大家分享面包，乐队奏起奥别列克舞曲和波尔卡，人人起舞。一整个夏天的劳作，化作一晚的欢乐。",
  "poles:ritual": "1683年9月12日黎明前，在被围困的维也纳（Wien）城外的卡伦山上，嘉布遣会修士马可·达维亚诺在一座破败的小礼拜堂里为援军举行弥撒。国王扬三世·索别斯基亲自在祭坛旁辅祭，他的儿子在这里被封为骑士。士兵们默默聆听弥撒，深知到了傍晚，基督教世界或许会赢得维也纳，也可能失去它。随后，索别斯基翻身上马，冲下山去投入战斗。",
  "poles:rain": "1980年8月，格但斯克列宁造船厂（Stocznia Gdańska im. Lenina）的工人因起重机操作员安娜·瓦伦蒂诺维奇被解雇而罢工。电工莱赫·瓦文萨翻过围栏来领导他们。整整十八天，罢工者守在厂门内，家人们隔着栏杆递进面包，神父们在厂区里主持弥撒。8月31日，政府签了字。团结工会（Solidarność）由此诞生，波兰开始相信世界可以改变。",
  "poles:flood": "1997年7月，连日暴雨后，奥德河及其支流暴涨，酿成「千年一遇大洪水」（Powódź tysiąclecia）。奥波莱、拉齐布日和克沃兹科被大水淹没；在弗罗茨瓦夫，学生和居民彻夜在大学和座堂岛周围堆垒沙袋。波兰有五十六人遇难。邻居们划着独木舟相互接送，许多人至今仍在房屋上标着当年水位的那条线。",
  "poles:wind": "在波德哈莱的塔特拉（Tatry）高地，「哈尔尼风」（halny）是一种温暖干燥的焚风，每逢秋春两季便从北坡呼啸而下。它的风速可达每小时一百公里，能吹倒成片的云杉林，掀掉扎科帕内木屋的屋顶。山民（górale）说，哈尔尼风会让人心神不宁、脾气暴躁。风一起，提琴手便停下琴弓，家家关上百叶窗，等待大山平静下来。",
  "poles:fire": "1944年8月1日，波兰国家军（Armia Krajowa）发动了反抗德国占领者的华沙起义（Powstanie warszawskie）。六十三天里，战士和平民坚持抵抗，在下水道中穿行往来，而苏军就在维斯瓦河（Wisła）对岸按兵不动。起义者投降后，希特勒下令将华沙夷为平地。德国爆破队一条街一条街地焚烧、炸毁这座城市，直到左岸城区约85%化为废墟。波兰人依据旧日的绘画，一砖一瓦地重建了老城（Stare Miasto）。",
  "poles:thunder": "2月2日圣烛节，波兰天主教徒把粗大的蜡烛带到教堂接受祝福。这就是「雷烛」（gromnica），得名于雷烛圣母（Matka Boża Gromniczna）——传说中她守护村庄免遭狼群侵袭。暴风雨来临时，人们在窗前点燃雷烛，使闪电不击中房屋。临终之人手中也会被放上一支雷烛，于是同一朵火焰既抵御风暴，又照亮通往上帝的路。",
  "poles:birth": "1473年2月19日，在维斯瓦河（Wisła）畔的商业城市托伦，一位铜商和妻子芭芭拉·瓦森罗德生下一个儿子。他随父亲取名米科瓦伊。他的舅舅是一位主教，出资供他在克拉科夫和意大利求学，希望他在教会中飞黄腾达。然而，尼古拉·哥白尼（Mikołaj Kopernik）却悄悄地把地球从宇宙的中心移开了，从此世界再也不是原来的样子。",
  "poles:death": "17、18世纪的波兰贵族以盛大的巴洛克排场下葬。一幅画在金属板上的「棺木肖像」（portret trumienny）被固定在棺材上，使逝者仿佛在注视着送葬的人们。灵柩停放在饰满纹章的灵台「哀悼城堡」（castrum doloris）之下。据记载，会有一名披甲骑士骑马进入教堂，折断一根长矛，或从马上跌落，以示这位骑士已经倒下。",
  // ——— Bohemians ———
  "bohemians:hunt": "想象：克日沃克拉特城堡（Křivoklát）矗立在布拉格（Praha）以西的王家森林中，波希米亚的国王们常来这里猎鹿、猎野猪。一个秋日清晨，年轻的瓦茨拉夫王子（Václav），也就是日后的查理四世（Karel IV.），带着猎人和猎犬，穿过贝龙卡河（Berounka）上方的山毛榉林策马而出。号角声从山谷中回荡。查理爱读书胜过打猎，但波希米亚的国王必须熟悉自己的森林，森林也必须认得自己的国王。",
  "bohemians:battle": "1420年7月14日，由西吉斯蒙德皇帝（Zikmund）召集的十字军围攻胡斯派控制的布拉格（Praha）。在维特科夫山（Vítkov）上，几十名胡斯派男女守着一座木制工事，抵挡德意志骑士。随后，独眼将领扬·杰式卡（Jan Žižka）从侧翼杀出，布拉格市民唱着《你们是上帝的战士》（Ktož jsú boží bojovníci）冲上山来。十字军溃散而逃。这座山至今仍叫杰式科夫（Žižkov），那首圣歌也成了胡斯派的战歌。",
  "bohemians:gather": "1357年7月9日清晨5点31分，查理四世皇帝（Karel IV.）为伏尔塔瓦河上的新石桥奠基。占星师选定这一刻，是因为它构成一个回文数——1357 9 7 5 31，又恰逢吉祥的行星排列。人群聚集在河岸上观看。这座桥就是今天的查理大桥（Karlův most），历时半个世纪才完工，此后一直把布拉格（Praha）的两岸连在一起。",
  "bohemians:ritual": "约1120年，编年史家布拉格的科斯马斯（Cosmas Pragensis）记载：女先知、公主莉布舍（Libuše）站在伏尔塔瓦河畔维谢赫拉德（Vyšehrad）的岩石上预言道：我看见一座伟大的城市，它的荣光将触及群星。她派人进入森林，寻找一个正在雕凿门槛（práh）的人，就在那里建城，取名布拉格（Praha）。数百年来，捷克人一直珍视这则预言；斯美塔那把她的异象写成了歌剧《莉布舍》的高潮。",
  "bohemians:rain": "1989年11月17日，警察在民族大街（Národní）殴打学生。此后，数十万捷克人日复一日涌入布拉格（Praha）的瓦茨拉夫广场（Václavské náměstí）。他们站在寒风中摇响钥匙，那声音像一口钟，告诉共产党政府：是时候回家了。瓦茨拉夫·哈维尔（Václav Havel）和亚历山大·杜布切克（Alexander Dubček）在阳台上发表讲话。他们等了四十年想要改变的世界，在十天之内就变了。",
  "bohemians:flood": "1342年2月，一场解冻让浮冰和洪水顺伏尔塔瓦河奔涌而下。冰块撞毁了尤迪特桥（Juditin most）的桥墩——这座老石桥自1170年代起就连接着布拉格（Praha）两岸——桥身大半塌入河中。此后十五年，布拉格人只能乘渡船或走木便桥过河，直到查理四世（Karel IV.）动工兴建新桥。此后伏尔塔瓦河又多次泛滥；2002年8月，洪水淹没了地铁和小城区（Malá Strana）。",
  "bohemians:wind": "想象：一场夏季狂风从西面横扫波希米亚高原。在舒马瓦（Šumava）森林里，云杉像稻草一样折断，整片山坡一下子倒伏。林中村落的玻璃匠靠木柴烧炉，他们望着这片废墟盘算：够烧好几年的柴火，可他们的森林没了。他们花了整整一季把木材运出，又重新种上树苗，明知自己看不到它们长成。",
  "bohemians:fire": "1415年7月6日，在康斯坦茨公会议（Konstanz）上，布拉格（Praha）的布道者扬·胡斯（Jan Hus）因拒绝认错被判为异端，处以火刑。西吉斯蒙德皇帝（Zikmund）曾许诺保他安全通行。点火时，他唱起了《垂怜经》。他的骨灰被撒入莱茵河（Rhein），不留下任何可作圣物的东西。消息传回波希米亚，以另一种方式让整个国家燃烧起来：胡斯革命爆发了。",
  "bohemians:thunder": "想象：雷声滚过波希米亚北部边境的克尔科诺谢山（Krkonoše），即巨人山脉。山民说，那是山神克拉科诺什（Krakonoš）发怒了，因为有人嘲笑了他，或欺骗了穷人。闪电击中山脊上一座牧羊人的小屋，牧羊人逃了出来。山谷里，他的家人低声说，他终究是个老实人，所以克拉科诺什饶了他。",
  "bohemians:birth": "1316年5月14日，波希米亚王后伊丽莎白（Eliška）在布拉格（Praha）生下一个儿子。他受洗取名瓦茨拉夫（Václav），与这片土地的主保圣人同名，承载着已与卢森堡家族结合的普热米斯尔王朝最后血脉的希望。他的父亲、盲王约翰（Jan Lucemburský）在他七岁时把他送往法国，他在那里改名查理（Karel）。作为查理四世皇帝，他使布拉格成为帝国首都，并创办了布拉格大学。",
  "bohemians:death": "1378年11月，查理四世皇帝（Karel IV.）去世，布拉格（Praha）为他举行了那个时代最隆重的葬礼。他的遗体在布拉格城堡停灵十一天；随后，数千人的队伍举着数百支火炬，牵着披黑布的马匹，护送他穿过全城前往圣维特大教堂（katedrála svatého Víta）。他治下各领地的旗帜被高举，又被降下。他所创办的大学的教授们称他为「祖国之父」（pater patriae）。",
  // ——— Slavs ———
  "slavs:hunt": "想象：公元6世纪，在第聂伯河（Днѣпръ）与维斯瓦河（Wisła）之间的沼泽森林里，一户斯拉夫人家设下套索捕野兔，又攀上空心树上的野蜂巢，用烟熏走蜜蜂取蜜和蜡。男人们带着长矛去对付野猪和熊。每次狩猎之前，他们都要先对森林精灵列希（леший）说几句话，免得他把人引入林中迷路。",
  "slavs:battle": "拜占庭作家畏惧斯克拉文人（Σκλαβηνοί）。约公元600年，莫里斯皇帝（Μαυρίκιος）的《战略》（Στρατηγικόν）告诫说：他们徒步作战，持小盾和标枪，从森林和沟壑中突袭，厌恶正面对阵。书中说，他们被偷袭时会沉入河流或池塘，躺在水底几个小时，用长长的空心芦苇呼吸，叫人无从知道战士藏在哪里。书中也承认：他们是自由的人，难以统治。",
  "slavs:gather": "约公元550年，历史学家普罗科匹厄斯（Προκόπιος）写道：斯克拉文人和安特人（Ἄνται）不受一人统治，而是生活在他所说的民主之中，一切事务无论好坏都在公众集会上共同决定。想象全村人聚在林间空地上，长老和户主们为战争、播种和裁决争论不休，直到达成一致。后来，斯拉夫人的市民大会维彻（вече）把这一习惯延续了好几个世纪。",
  "slavs:ritual": "在吕根岛上的阿尔科纳（Arkona），波罗的海斯拉夫人供奉着四面神斯万特维特（Svantevit）的神庙。编年史家萨克索·格拉玛提库斯（Saxo Grammaticus）记述祭司如何就战事求问神意：把长矛一排排摆在地上，再牵着神的白马从上面走过。如果马先迈右脚且没有碰到任何一支矛，战争就会顺利。全族人都屏息等待那匹马的蹄子。",
  "slavs:rain": "遇上干旱，南斯拉夫的村庄会举行多多拉（додола）求雨仪式。一个女孩从头到脚披上绿叶和青草，由其他女孩领着挨家挨户走，向天空唱歌求雨。每到一户，主妇便往多多拉身上泼水，女孩转起圈来把水甩回去，仿佛她自己就是雨。然后大家望着云，静静等待。",
  "slavs:flood": "想象：普里皮亚季沼泽的春天来得很晚。积雪一下子全部融化，河水漫过森林，村庄成了一座座孤岛。人们把粮食和孩子装进独木舟，划向高地，赶着牛群在浅水中前行。老妇人说，是水妖沃佳诺伊（водяной）和水仙女鲁萨尔卡（русалки）来取它们的那一份了，于是把一条面包抛进洪水里。",
  "slavs:wind": "想象：《往年纪事》（Повѣсть времѧньныхъ лѣтъ）把斯特里博格（Стрибогъ）列为古斯拉夫人的神祇之一，后世诗人称风为斯特里博格的孙子。当秋天的大风暴撕裂森林、掀起屋顶的茅草时，村民们说斯特里博格发怒了。他们在树上系一条丝带，把面粉撒进风里喂它，盼它掠过田野时放过庄稼。",
  "slavs:fire": "在一年中最短的夜晚——库帕拉之夜（Купальская ночь），斯拉夫青年聚在河边点起大篝火。情侣们手牵着手一起跃过火焰；若手没有松开，爱情就会长久。姑娘们把插着蜡烛的花环放入水中，看它漂向何方来占卜未来。传说蕨类只在这一夜开出火红的花，谁找到它，谁就能找到宝藏。",
  "slavs:thunder": "约公元550年，普罗科匹厄斯（Προκόπιος）写到斯拉夫人：他们相信唯有一位神，即闪电的创造者，是万物之主，并向他献祭牛和各种牺牲。这位神就是雷神佩伦（Перунъ），他用斧头击打巨蛇韦莱斯（Велесъ）。橡树是他的树，星期四是他的日子。当雷声在森林上空炸响，斯拉夫人听见的是佩伦与巨蛇在天空中翻滚的搏斗。",
  "slavs:birth": "斯拉夫人相信，孩子出生后的第三个夜晚，三位命运女神——罗扎尼察（рожаницы）或苏德尼察（суденици）——会隐身来到摇篮边，宣告孩子的命运：他的财富、他的婚姻、他的死期。母亲为她们摆上面包、盐和酒，并让一盏灯整夜亮着。亲戚们设法不睡，想偷听裁决。也有人祈祷这个孩子能为家族带来好运。",
  "slavs:death": "早期斯拉夫人在大柴堆上火化死者，在骨灰上堆起坟丘库尔干（курганы），或把骨灰装进陶瓮置于路旁的木桩上。火化之后是特里兹纳（тризна），一场为纪念死者而举行的葬宴，伴有竞技和模拟战斗；还有斯特拉瓦（strava），即在墓旁共享的餐食。后来在拉多尼察节（Радоница）等亡灵节日里，家人会带着食物来到坟前，相信祖先会回来一同享用。",
  // ——— Rus ———
  "rus:hunt": "约1117年，弗拉基米尔·莫诺马赫大公（Володимеръ Мономахъ）在写给儿子们的《训诫书》（Поученье）中夸耀自己的狩猎经历：两头原牛用角把我连人带马挑起；一头鹿用角顶伤了我；一头驼鹿踩踏我，另一头用角撞我；一头野猪把我腿边的剑扯了下来；一头熊咬住了我膝旁的鞍褥。他说，他亲自打猎，从不交给仆人去做。他又补充道：是上帝保佑了我。",
  "rus:battle": "971年，基辅（Кыѥвъ）大公斯维亚托斯拉夫（Святославъ）被拜占庭皇帝约翰·齐米斯基斯（Ἰωάννης Τζιμισκής）围困在多瑙河畔的多罗斯托隆（Δορόστολον）。《往年纪事》（Повѣсть времѧньныхъ лѣтъ）记下他对寡不敌众的部下的讲话：我们不要使罗斯的土地蒙羞（да не посрамимъ земли Рускыя），宁可在此化为白骨，因为死者无耻辱可言。若我们逃跑，便会蒙受耻辱。斯维亚托斯拉夫正是那位进攻前先警告敌人的大公：我要来攻打你们了。对罗斯人来说，这就是荣誉。",
  "rus:gather": "在罗斯的大商城诺夫哥罗德（Новъгородъ），自由市民听到雅罗斯拉夫宫院（Ярославово дворище）的一口特殊钟声，便会前来参加市民大会维彻（вѣче）。他们在露天聚集，呼喊争论，选举城市的行政长官波萨德尼克（посадникъ），甚至选举大主教，还能迎立或驱逐王公。这口钟是城市自由的声音，因此当莫斯科（Москва）的伊凡三世（Иван III）在1478年终结诺夫哥罗德的独立时，把它带走了。",
  "rus:ritual": "《往年纪事》（Повѣсть времѧньныхъ лѣтъ）记载，987年，基辅（Кыѥвъ）大公弗拉基米尔（Володимеръ）派使者考察邻邦的信仰，为自己的人民寻找真神。在君士坦丁堡（Κωνσταντινούπολις），使者们参加了圣索菲亚大教堂（Ἁγία Σοφία）的礼拜，回来禀报说：我们不知道自己是在天上还是在人间，因为人间没有这样的辉煌。988年，弗拉基米尔受洗，基辅的百姓也在第聂伯河（Днѣпръ）中受洗。",
  "rus:rain": "《往年纪事》（Повѣсть времѧньныхъ лѣтъ）记载，862年，北方的斯拉夫和芬兰部落陷于纷争。他们厌倦了内斗，便派人渡海去找瓦良格罗斯人，传话说：我们的土地广大而富饶，但没有秩序（Земля наша велика и обильна, а наряда в ней нѣтъ）。请来统治我们吧。留里克（Рюрикъ）和他的兄弟们来了。无论是传说还是史实，它都记下了一个民族对世界安定、和平到来的等待与期盼。",
  "rus:flood": "想象：每年四月，第聂伯河（Днѣпръ）在基辅（Кыѥвъ）漫溢，春汛（половодье）让河水铺满左岸的草地，远处的对岸仿佛消失了。在城里过冬的商人们整备船只——用整棵树凿成的独木舟（μονόξυλα）——准备南下前往君士坦丁堡（Κωνσταντινούπολις）。高涨的河水载着他们越过险滩，否则那些险滩会把船撞得粉碎。对罗斯人来说，洪水就是一年贸易的开始。",
  "rus:wind": "860年，一支约两百艘船的罗斯舰队趁皇帝不在，出现在君士坦丁堡（Κωνσταντινούπολις）城下，洗劫了城郊。牧首佛提乌（Φώτιος）在布道中讲述了城中的恐慌。后来拜占庭和罗斯的传说称，牧首把圣母的长袍浸入海中，一场风暴骤然而起，罗斯人的船被撞碎在岸边。幸存的罗斯人回到家乡，讲述希腊人之神的威力。",
  "rus:fire": "945年，德列夫利安人（деревляне）杀死了基辅（Кыѥвъ）大公伊戈尔（Игорь）。他的遗孀奥莉加（Ольга）展开复仇。《往年纪事》（Повѣсть времѧньныхъ лѣтъ）记载，946年，她长期围困伊斯科罗斯坚（Искоростень）后，只索要一份微薄的贡品：每户三只鸽子、三只麻雀。她的士兵把点燃的硫磺绑在鸟脚上放飞；鸟儿飞回屋檐下的巢中，全城顿时燃起大火。奥莉加后来成了基督教圣徒。",
  "rus:thunder": "980年，弗拉基米尔大公（Володимеръ）在基辅（Кыѥвъ）的山丘上立起雷神佩伦（Перунъ）的神像，银头金须。988年受洗之后，他下令把神像拴在马尾上，用棍棒抽打，再扔进第聂伯河（Днѣпръ）。《往年纪事》（Повѣсть времѧньныхъ лѣтъ）说，雷神顺流漂去时，人们哭泣不已；每当神像靠岸，就有人沿岸奔跑把它推开，直到它漂过险滩。",
  "rus:birth": "想象：在基辅（Кыѥвъ）的一座木屋里，一位罗斯贵妇在漫长的冬天分娩。接生婆用亚麻线扎好脐带；父亲是大公亲兵队（дружина）中的一名瓦良格商人，他把一把小剑贴在摇篮上，好让男孩长大后勇敢无畏。第八天，神父将为他施洗。一位亲戚盼他将来保卫基辅、抵御草原游牧民；另一位却担心他会因此早早送命。",
  "rus:death": "922年，阿拉伯使者伊本·法德兰（ابن فضلان）在伏尔加河（Волга）畔目睹了一位罗斯首领的葬礼。死者被安放在他的船中，身穿丝绸，身旁摆着食物、饮料和兵器；一名自愿随他而去的女奴被一位叫作「死亡天使」的老妇杀死。随后，船被点燃。一个罗斯人对伊本·法德兰说：你们阿拉伯人真傻。我们一眨眼就把他烧了，他直接就去了天堂。",
  // ——— Russians ———
  "russians:hunt": "1645年至1676年在位的沙皇阿列克谢·米哈伊洛维奇（Алексей Михайлович）在一切消遣中最爱鹰猎。1656年，他主持编写了一部狩猎规章《鹰猎之道条例》（Урядникъ сокольничья пути），规定新鹰手接受第一只猎鹰的仪式。他在莫斯科（Москва）近郊养着数千只鹰隼，还写信给首席鹰手询问它们的健康。他说，鹰猎是乱世中的一份心头之乐。",
  "russians:battle": "1380年9月8日，莫斯科大公德米特里（Дмитрий）在顿河畔的库利科沃原野（Куликово поле）迎战金帐汗国马麦（Мамай）的大军。相传战斗以一场决斗开始：圣谢尔盖（Сергий）派来的修士亚历山大·佩列斯韦特（Александр Пересвет）策马迎战鞑靼勇士切卢别伊（Челубей），两人在第一次交锋中同归于尽。随后的战斗惨烈而漫长，但德米特里获胜，被称为「顿斯科伊」（Донской）。俄罗斯人把这一战视为民族解放的开端。",
  "russians:gather": "在大斋期前的谢肉节（Масленица），即「黄油周」，俄罗斯人聚在一起享受斋戒前的最后一场盛宴。他们吃一摞摞布林饼（блины），饼又圆又金黄，好似归来的太阳；他们从冰山上滑雪橇，举行拳斗，乘三驾马车（troika）兜风，走访姻亲。最后一天是宽恕星期日（Прощёное воскресенье），人人互相请求原谅，并焚烧谢肉节夫人的草人，把冬天送走。",
  "russians:ritual": "1380年8月，在出征迎击马麦（Мамай）之前，德米特里大公（Дмитрий）骑马来到三一修道院（Троицкий монастырь），请求院长拉多涅日的谢尔盖（Сергий Радонежский）祝福。谢尔盖与他一同祈祷，据《谢尔盖行传》记载，他对大公说：你将战胜你的敌人。他还派了两名修士佩列斯韦特（Пересвет）和奥斯利亚比亚（Ослябя）随他出战。在俄罗斯人心中，这是君主借圣者之口向上帝询问未来的画面。",
  "russians:rain": "1480年10月，莫斯科（Москва）大公伊凡三世（Иван III）与大帐汗国的阿合马汗隔着乌格拉河（Угра）对峙。双方都不肯渡河。他们等了好几个星期，隔着河水互相叫骂，伊凡的神职人员则恳求他出战。后来冬天来了，河面开始结冰，补给短缺的阿合马撤军了。「乌格拉河对峙」（Стояние на Угре）不经一战便结束了鞑靼之轭。俄罗斯是在等待中改变的。",
  "russians:flood": "1824年11月7日，一场来自芬兰湾（Финский залив）的风暴把涅瓦河（Нева）倒灌进圣彼得堡（Санкт-Петербург）。水位上涨超过四米，街道变成河流，房屋漂浮。数百人溺亡。普希金（Пушкин）以此为《青铜骑士》（Медный всадник）的背景：小职员叶甫盖尼（Евгений）在洪水中失去爱人，精神失常，向在沼泽上建城的彼得大帝（Пётр Великий）雕像挥拳，而那雕像竟策马追赶他。",
  "russians:wind": "想象：冬日的奥伦堡（Оренбург）草原上，天空变得一片苍白，一场暴风雪（буран）骤然而起。一辆载着车夫和年轻军官的雪橇几分钟内就迷了路；马停了下来，空中满是飞雪。车夫说：老爷，这是暴风雪，我们得等。他们裹着羊皮袄坐着，听狂风呼啸——正如普希金（Пушкин）在《上尉的女儿》（Капитанская дочка）中所写——祈祷能看见一点灯光。",
  "russians:fire": "1812年9月14日，拿破仑（Napoléon）的大军（Grande Armée）进入几乎空无一人的莫斯科（Москва）。当夜，城中四处起火；总督罗斯托普钦伯爵（Ростопчин）事先撤走了消防水泵，许多人相信是他下令焚城。这座木头城市燃烧了四天，四分之三化为灰烬。拿破仑在克里姆林宫（Кремль）观望，说道：多么了不起的民族！他们是斯基泰人。俄罗斯人宁可舍弃他们的圣城，也不投降。",
  "russians:thunder": "在俄罗斯民间信仰中，先知以利亚——伊利亚（Илья）——驾着火焰战车驶过天空，雷声就是车轮的轰鸣。8月2日的伊利亚节（Ильин день）是风暴之日；农民不下地干活，怕被伊利亚击中，并且要在这天之前收完干草。暴风雨来时，人们在圣像前点燃蜡烛祈祷，因为闪电是上帝的惩罚。",
  "russians:birth": "1672年5月30日，在克里姆林宫（Кремль），皇后娜塔莉娅·纳雷什金娜（Наталья Нарышкина）为沙皇阿列克谢（Алексей）生下一个儿子。莫斯科（Москва）的钟声一连响了好几天，男孩在丘多夫修道院（Чудов монастырь）受洗，取名彼得（Пётр）。他是幼子，很少有人料到他会继位；他同父异母兄长的家族图谋害他，他在恐惧中长大。后来，他作为彼得大帝把俄罗斯拽向西方，并在海边建起一座新都。",
  "russians:death": "按照俄罗斯东正教习俗，死者在家中被清洗、停放，镜子被遮住，一支蜡烛长明。人们通宵诵读《诗篇》。下葬之后，在第三天、第九天和第四十天举行追思，人们相信灵魂在这期间走向审判。家人吃一种叫库季亚（кутья）的甜麦粥，用蜂蜜和葡萄干拌成。复活节后的拉多尼察节（Радоница），他们去扫墓，与亡者分享食物，并说：基督复活了（Христос воскресе）。",
  // ——— Magyars ———
  "magyars:hunt": "匈牙利编年史记载着神鹿（Csodaszarvas）的传说。梅恩罗特（Ménrót）的两个儿子胡诺尔（Hunor）和马戈尔（Magor）在打猎时，一头白鹿出现在他们面前。他们追着它穿过迈奥提斯沼泽，追了好几天，直到它消失在一片丰美的牧场上。兄弟俩在那里遇见一位王公的女儿们，娶她们为妻，成了匈人和马扎尔人的祖先。一场狩猎，把一个民族引向了家园。",
  "magyars:battle": "1526年8月29日，年轻的匈牙利国王路易二世（II. Lajos）在莫哈奇（Mohács）迎战苏莱曼大帝（سلیمان قانونی）的大军。匈牙利重骑兵英勇冲锋，却在不到两小时内被奥斯曼的大炮和禁卫军撕得粉碎。七位主教和大部分贵族阵亡。路易在逃跑时被身披铠甲的坐骑压在身下，溺死在涨水的切莱溪（Csele）中。直到今天，匈牙利人遇到不幸时还会说：在莫哈奇损失的更多（több is veszett Mohácsnál）。",
  "magyars:gather": "《匈牙利人事迹》（Gesta Hungarorum）记载，约895年马扎尔人进入喀尔巴阡盆地（Kárpát-medence）之前，七个部落的首领——「七马扎尔」（Hétmagyar）——聚在一起立下血誓。每人割破手臂，让血流进同一只杯中；他们推举阿尔莫什（Álmos）及其子阿尔帕德（Árpád）为领袖，并发誓共享一切所得。七个部落的人民在那只杯子下合为一体。",
  "magyars:ritual": "使匈牙利皈依基督教的国王圣伊什特万一世（I. István），眼看着独子伊姆雷（Imre）于1031年死于狩猎。相传他在1038年去世前，没有继承人，又担忧这个年轻的王国，便举起王冠，把匈牙利献给圣母玛利亚，请她庇护。从此匈牙利人称自己的国家为「玛利亚王国」（Regnum Marianum），画作中常描绘这位老国王双手捧冠下跪的情景。",
  "magyars:rain": "想象：夏季干旱时节的匈牙利大平原（Alföld）上，霍尔托巴吉（Hortobágy）的牧人仰望天空。水井干涸，灰牛垂着头站立。地平线上闪烁着「délibáb」——湖泊与城镇漂浮在空中的海市蜃楼，它的许诺何其残忍。骑马的牧人（csikós）每天清晨出发，向西眺望寻找云彩。当雷声终于响起，整片普斯陶草原（puszta）仿佛重新呼吸起来。",
  "magyars:wind": "想象：一场夏日风暴横扫普斯陶草原（puszta）。方圆数里没有一棵树，狂风迎面扑向马群；身穿宽大蓝衫的骑马牧人（csikós）绕着受惊的马群奋力奔驰，不让它们狂奔冲进沼泽。帽子飞走，鞭子噼啪作响，牧人们在雨中相互呼喊。到黎明时分，他们清点马群，运气好的话，一匹也没少。",
  "magyars:fire": "1552年9月至10月，由伊什特万·多博（István Dobó）指挥的小小埃格尔城堡（Eger），抵挡奥斯曼大军达39天之久。敌人爬上城墙时，守军抛下火轮、燃烧的沥青和着火的木桶；埃格尔的妇女也加入战斗，倾倒滚水、投掷石块。地道被一一挫败，火势被一一扑灭。奥斯曼军最终撤退。盖萨·加尔东尼（Gárdonyi Géza）的小说《埃格尔之星》（Egri csillagok）让这段历史成了每个孩子都知道的故事。",
  "magyars:thunder": "想象：10世纪，在皈依基督教之前，一位马扎尔萨满「塔尔托什」（táltos）在暴风雨逼近营地时登上山顶。人们相信塔尔托什会化身为公牛或火焰在云中作战，与其他精灵搏斗，以决定是否降下冰雹。山下的人们望着闪电，听着雷声，等着知道谁赢了，他们的庄稼和马匹能否幸免。",
  "magyars:birth": "编年史记载，马扎尔首领于盖克（Ügyek）的妻子埃梅舍（Emese）梦见一只巨大的猎鹰图鲁尔（turul）降临在她身上，从她腹中流出一条河，流向异国他乡，她的后代中将出现荣耀的君王。她的儿子取名阿尔莫什（Álmos），源自「álom」，意为梦。阿尔莫什之子阿尔帕德（Árpád）率领马扎尔人进入喀尔巴阡盆地（Kárpát-medence），建立了统治匈牙利四百年的王朝。",
  "magyars:death": "在10世纪的马扎尔墓葬中，考古学家发现战士以一种特殊方式与马同葬：不是整匹马，而是马皮——填充或折叠起来——连同马头骨、下肢和马蹄，放在骑手脚边。他身旁有弓、箭、马刀和马镫，有时还有一块银制的箭囊袋饰板。家人相信，战士将骑着这匹马进入另一个世界，依然是一名骑手。",
  // ——— Bulgarians ———
  "bulgarians:hunt": "想象：秋天的罗多彼山（Родопи）中，保加利亚牧人和猎人攀上松林山坡，追猎岩羚羊和野猪。狩猎也是守护：熊和狼威胁着羊群。傍晚的篝火旁，有人吹起羊皮风笛盖达（гайда），一位老猎人讲起马尔科王子（Крали Марко）与山中猛兽搏斗的故事。猎物的肉被分给众人，兽皮挂在阳光下晾晒。",
  "bulgarians:battle": "811年7月，拜占庭皇帝尼基弗鲁斯一世（Νικηφόρος Αʹ）入侵保加利亚，焚毁了克鲁姆汗（Крум）的都城普利斯卡（Плиска）。回师途中，他的军队被困在瓦尔比察（Varbitsa）山口，去路被木墙堵死。7月26日黎明，保加利亚人发起进攻。尼基弗鲁斯阵亡，这是数百年来第一位战死沙场的皇帝。编年史说，克鲁姆把他的头骨镶上银，与贵族们用它饮酒。",
  "bulgarians:gather": "3月1日，保加利亚人互赠马尔蒂尼察（мартеници）——用红白两色毛线拧成的小穗——并说「Chestita Baba Marta」（Честита Баба Марта），即「三月奶奶节快乐」。人人把它别在衣服上或系在手腕上，直到看见第一只鹳或燕子，或一棵开花的树，再把马尔蒂尼察系到树枝上。整座整座的城市开满红白之花，人们互祝在即将到来的春天里健康平安。",
  "bulgarians:ritual": "866年，刚刚受洗的保加利亚大公鲍里斯一世（Борис I）向教宗尼古拉一世（Nicolaus I）寄去一份106个问题的清单，询问他的人民应如何作为基督徒生活。可以穿裤子吗？他们带上战场的马尾军旗该怎么处置？星期日可以干活吗？教宗一一作答。鲍里斯想知道，在新的上帝之下，他的人民将拥有怎样的未来，他问得极其认真。",
  "bulgarians:rain": "夏季干旱时，保加利亚村庄会举行佩佩鲁达（пеперуда）——「蝴蝶」——仪式。一个小女孩，通常是孤儿，穿上用绿叶和藤蔓编成的裙子，由其他孩子领着挨家挨户走，唱道：飞吧，飞吧，佩佩鲁达，给我们下雨吧。每到一家门口，女主人便往她身上泼水，再送些面粉或鸡蛋。然后全村人仰望天空，等待云从山那边飘来。",
  "bulgarians:flood": "想象：多瑙河（Дунав）下游的春天。半个欧洲的融雪汇入河中，水位上涨，漫过锡利斯特拉（Силистра）和斯维什托夫（Свищов）下游的湿地。渔民把船挪到柳树边，农民把牛赶上高岸。多瑙河畔的村庄里，人们回忆起往年的洪水，以及祖辈熬过洪水的办法，静候河水退去——因为它总会留下肥美的鱼和黑色的沃土。",
  "bulgarians:wind": "想象：一场冬季风暴从北方越过黑海，扑向保加利亚海岸。在岩石半岛上的内塞伯尔（Несебър），巨浪越过古老的城墙，浪花溅到中世纪的教堂上。渔民把船拖上岸，牢牢绑住。在圣斯特凡教堂里，一位老妇人为水手的守护者圣尼古拉点燃蜡烛，为仍在海上的船只祈祷。",
  "bulgarians:fire": "在斯特兰贾山（Странджа）的村庄里，每年5月21日圣君士坦丁与圣海伦娜节（Св. Константин и Елена），「涅斯蒂纳里」（нестинари）赤脚在通红的炭火上起舞。他们手捧圣像，在鼓声和风笛声中进入出神状态，踏上炭火起舞而不被灼伤。人们相信他们在出神时会为村庄预言来年之事。这一习俗已被列入联合国教科文组织非物质文化遗产名录。",
  "bulgarians:thunder": "想象：在保加利亚的村庄里，先知以利亚——圣伊利亚（Свети Илия）——是雷电和冰雹的主宰，7月20日他的节日是一个令人敬畏的日子。这一天没有人下地干活。当黑沉沉的风暴在巴尔干山脉（Стара планина）上空聚集，一位老妇人取出复活节祝圣过的面包放在门槛上，画着十字祈祷，愿冰雹绕过正在成熟的麦田。",
  "bulgarians:birth": "在保加利亚民间信仰中，孩子出生后的第三个夜晚，三位命运女神奥里斯尼察（орисници）会来到家中决定孩子的命运。家人备好一桌面包、蜂蜜和酒，打扫地面，门不上锁。母亲和祖母守候着，盼望在梦中得知判决。孩子或许会成为伟大的英雄，或许会早夭；奥里斯尼察不会透露，也没有人能改变她们的话。",
  "bulgarians:death": "1014年克莱迪昂（Κλειδίον）战役之后，拜占庭皇帝巴西尔二世（Βασίλειος Βʹ）把约一万五千名保加利亚俘虏刺瞎，每一百人中留一人保有一只眼睛，带领其他人回家。当这支失明的军队抵达普里莱普（Прилеп）时，沙皇萨穆伊尔（Самуил）一见便昏倒在地，两天后去世。在保加利亚人的记忆中，这是一位沙皇为他的士兵心碎而死的故事——是一种哀痛，而非一场失败。",
  // ——— Byzantines ———
  "byzantines:hunt": "想象：在博斯普鲁斯海峡（Βόσπορος）对岸比提尼亚（Βιθυνία）的山丘上，一位拜占庭贵族骑马出猎，身后马臀上坐着一头训练有素的猎豹（πάρδος），像猎鹰一样戴着头罩。驱赶者把一只瞪羚从灌木丛中赶出；头罩摘下，猎豹一跃而下，飞奔而去。仆人们带着猎犬和猎鹰紧随其后。傍晚有美酒、音乐和宫廷闲谈，隔着海水，都城的圆顶闪闪发光。",
  "byzantines:battle": "1453年5月29日凌晨，穆罕默德二世（محمد ثانی）的奥斯曼大军猛攻君士坦丁堡（Κωνσταντινούπολις）的城墙。末代皇帝君士坦丁十一世·巴列奥略（Κωνσταντῖνος ΙΑʹ Παλαιολόγος）前一天傍晚在圣索菲亚大教堂（Ἁγία Σοφία）领了圣餐，并请求所有人宽恕。据说，奥斯曼军破城时，他扔掉了皇帝的徽饰，作为一名普通士兵冲入战斗。他的遗体始终未能确认。千年帝国就在那个清晨终结。",
  "byzantines:gather": "君士坦丁堡（Κωνσταντινούπολις）的竞技场（Ἱππόδρομος）大约能容纳十万人观看战车比赛，观众分为蓝党（Βένετοι）和绿党（Πράσινοι）。532年1月，两派联合起来反对查士丁尼（Ἰουστινιανός），高呼「尼卡」（Νίκα）——「胜利！」——并放火焚城。查士丁尼准备出逃，但据普罗科匹厄斯（Προκόπιος）记载，皇后狄奥多拉（Θεοδώρα）说：皇权是最好的裹尸布。皇帝留了下来；军队把人群困在竞技场中，约三万人丧生。新的圣索菲亚大教堂（Ἁγία Σοφία）从灰烬中拔地而起。",
  "byzantines:ritual": "626年夏，阿瓦尔人、斯拉夫人和波斯人围攻君士坦丁堡（Κωνσταντινούπολις），而希拉克略皇帝（Ἡράκλειος）远在东方。牧首塞尔吉乌斯（Σέργιος）抬着圣母像沿城墙游行，百姓日夜向她祈祷。当敌方舰队被摧毁、阿瓦尔人撤退后，全城人在教堂里站立通宵感恩，向他们的守护者诞神女（Θεοτόκος）高唱《不坐颂》（Ἀκάθιστος）——一首不坐着唱的赞美诗。",
  "byzantines:rain": "1453年春，被围困的君士坦丁堡（Κωνσταντινούπολις）等待着西方许诺派来的威尼斯舰队。5月3日，一艘小船悄悄穿过奥斯曼封锁线去寻找援军。它在爱琴海上搜寻了三个星期，一无所获。5月23日，水手们带着消息回来了，明知自己回来几乎必死无疑。他们说，回来是他们的职责。全城人明白了：援军不会来了。",
  "byzantines:flood": "525年4月，戴桑河（ܕܝܨܢ）冲破了美索不达米亚埃德萨（ܐܘܪܗܝ）的城墙——那是帝国伟大的基督教城市之一。编年史说，洪水冲走了房屋、教堂和浴场，数千人在夜里溺亡。查士丁一世皇帝（Ἰουστῖνος Αʹ）拨款重建，该城为表感激改名为查士丁诺波利斯（Ἰουστινούπολις）。工程师们开凿了一条新河道，让河水绕城而过，使洪水再也不能回来。",
  "byzantines:wind": "想象：深秋时节，来自亚历山大港（Ἀλεξάνδρεια）的运粮船队迟迟未到。一场北风沿着博斯普鲁斯海峡（Βόσπορος）、越过马尔马拉海（Προποντίς）已经刮了好几天，靠埃及面包为生的君士坦丁堡（Κωνσταντινούπολις）居民站在海墙上眺望船帆。面包师已经把面包做得更小了。教堂里，人们向水手的守护者圣尼古拉祈祷。当船队终于出现时，全城一片欢呼。",
  "byzantines:fire": "670年代，阿拉伯舰队围攻君士坦丁堡（Κωνσταντινούπολις），一位来自叙利亚的难民建筑师卡利尼科斯（Καλλίνικος）给拜占庭人带来一种新武器：从船首铜制虹吸管中喷射出的液体火焰。它在水面上也能燃烧，用水扑不灭。阿拉伯舰队被摧毁。这种「希腊火」（ὑγρὸν πῦρ）——海上之火——的配方作为国家机密保守得如此严密，至今仍无人知晓。",
  "byzantines:thunder": "1453年5月25日，围城期间，君士坦丁堡（Κωνσταντινούπολις）的人们抬着引路圣母（Ὁδηγήτρια）像穿过街道，为城市祈祷。圣像突然从抬像人手中滑落，几乎无法再抬起。随后，一场猛烈的雷暴和冰雹袭来，雨势之大几乎把孩子冲走。第二天，浓雾笼罩全城。许多人认为，这些都是上帝撤回庇护的征兆。",
  "byzantines:birth": "想象：在君士坦丁广场（Φόρος Κωνσταντίνου）附近的一座房子里，一位商人的妻子正在分娩。接生婆在床边挂起圣母和圣安妮的护身符，家里的神父拿着圣油等候。女婴啼哭起来；第八天她将被命名，第四十天将随母亲被带到教堂。父亲希望她将来嫁个好人家；经历过瘟疫的祖母只是祈祷她能活下来。",
  "byzantines:death": "拜占庭人以哀歌和希望悼念亡者。遗体被清洗、穿戴整齐后抬进教堂，送葬者一边唱着「来吧，让我们献上最后的亲吻」（Δεῦτε τελευταῖον ἀσπασμὸν δῶμεν），一边献上最后一吻。在第三天、第九天和第四十天，人们分食科利瓦（κόλλυβα）——用蜂蜜和坚果拌的煮麦粒，象征复活。几百年间，皇帝们都被安葬在圣使徒教堂（Ἅγιοι Ἀπόστολοι）的斑岩石棺中，靠近君士坦丁大帝（Κωνσταντῖνος ὁ Μέγας）的陵墓。",
  // ——— Macedonian Dynasty ———
  "macedonian-dynasty:hunt": "886年8月，巴西尔一世（Βασίλειος Αʹ）——这位出身亚美尼亚农民、白手起家创立马其顿王朝的皇帝——在色雷斯（Θρᾴκη）打猎时，一头巨鹿转身向他扑来。编年史家说，鹿角钩住了他的腰带，把他从马上拖进森林，直到一名仆人用剑割断了腰带。年迈的皇帝怀疑有人谋害，下令惩罚那名对他拔刀的仆人，几天后他因伤去世。",
  "macedonian-dynasty:battle": "960年，将军尼基弗鲁斯·福卡斯（Νικηφόρος Φωκᾶς）率领一支载有希腊火的庞大舰队驶向被阿拉伯埃米尔占据了一个多世纪的克里特岛（Κρήτη）。他全副武装登陆，骑兵直接从船上的跳板策马冲上岸。他围攻坎达克斯（Χάνδαξ）要塞整整一个冬天，961年3月7日，要塞陷落。君士坦丁堡（Κωνσταντινούπολις）在竞技场（Ἱππόδρομος）举行凯旋式庆祝。九年后，尼基弗鲁斯本人成了皇帝。",
  "macedonian-dynasty:gather": "949年，来自意大利的使节克雷莫纳的柳特普兰德（Liutprandus Cremonensis）在马格瑙拉宫（Μαγναύρα）受到君士坦丁七世皇帝（Κωνσταντῖνος Ζʹ）的接见。他描述了会咆哮、会甩尾的金狮子，金树上歌唱的机械鸟，还有那张宝座——当他鞠躬时，宝座突然升向天花板，等他抬起头，皇帝已换上新袍高高坐在上方。整个宫廷都聚在一旁，观赏外国人的惊愕。",
  "macedonian-dynasty:ritual": "被称为「智者」的利奥六世皇帝（Λέων ΣΤʹ）学识渊博，以至于后人把《智者利奥神谕》归在他名下——一部由谜语和图画组成的书，据说预言了历代皇帝和君士坦丁堡（Κωνσταντινούπολις）的命运。拜占庭人在危急时刻会翻阅它，从晦涩的诗句中解读统治者的到来以及都城的陷落或得救。他们相信未来早已写定，智者能在肃穆的沉默中读懂它。",
  "macedonian-dynasty:rain": "编年史家写道，927年至928年的冬天，帝国的土地冻得坚硬，长达120天。庄稼歉收，随之而来的是大饥荒。与年幼的君士坦丁七世（Κωνσταντῖνος Ζʹ）共治的罗曼努斯·利卡潘努斯皇帝（Ῥωμανὸς Λεκαπηνός）下令在君士坦丁堡（Κωνσταντινούπολις）的柱廊下为穷人搭建木棚，并每月发放食物和钱。人们等待着春天，等待大地宽恕他们。",
  "macedonian-dynasty:flood": "想象：10世纪，比提尼亚（Βιθυνία）的桑加里奥斯河（Σαγγάριος）在连下数周雨后上涨，漫过查士丁尼（Ἰουστινιανός）所建大石桥下方的平原。石桥屹立不倒，正如四百年前建造者所承诺的，但周围的村庄都被淹了。农民们带着山羊和粮袋挤上桥，附近修道院的修士们划船出去接应被困的人，一边划桨一边唱着诗篇。",
  "macedonian-dynasty:wind": "想象：一支帝国舰队从金角湾（Χρυσοῦν Κέρας）出发去迎击阿拉伯海盗，在爱琴海遭遇大风。德罗蒙战舰（δρόμωνες）折断了桨和桅杆，希腊火的虹吸管被牢牢绑住，以免松脱。海军将领跪在甲板上发誓：若能生还，便为圣母修建一座教堂。三天后，伤痕累累的舰队蹒跚驶入纳克索斯岛（Νάξος），水手们在岸上感恩祈祷。",
  "macedonian-dynasty:fire": "941年6月，基辅（Кыѥвъ）大公伊戈尔（Игорь）率领庞大舰队进攻君士坦丁堡（Κωνσταντινούπολις）。罗曼努斯·利卡潘努斯皇帝（Ῥωμανὸς Λεκαπηνός）城中只有十五艘旧船，他在船首、船尾和两舷都装上了希腊火虹吸管。贵族（πατρίκιος）塞奥法尼斯（Θεοφάνης）率船出战。罗斯人逼近时，火焰倾泻到他们的船上；罗斯战士身披铠甲跳入海中。幸存者回到基辅说，希腊人掌握着来自天上的闪电。",
  "macedonian-dynasty:thunder": "想象：先知以利亚节期间，一场夏日雷暴在君士坦丁堡（Κωνσταντινούπολις）上空炸开。闪电击中广场上一根柱子顶端的青铜雕像，人群聚拢过来看那被熏黑的金属。有人说这是对皇帝的预兆；也有更务实的人指指天空，匆匆回家。在大皇宫（Μέγα Παλάτιον）里，书记官把这件事记入编年史，好让智者去解读。",
  "macedonian-dynasty:birth": "905年9月，利奥六世皇帝（Λέων ΣΤʹ）的情妇佐伊·卡波诺普西娜（Ζωὴ Καρβωνοψίνα）在紫室（Πορφύρα）生下一个儿子——紫室是宫中墙壁呈紫色、皇家子女降生的房间。这个男孩就是君士坦丁七世（Κωνσταντῖνος Ζʹ），人称「生于紫室者」（Πορφυρογέννητος）。他的父母并未成婚，当利奥娶佐伊为第四任妻子时，教会提出了抗议。许多人担心这个孩子会引发教会分裂；结果他却成了一位学者皇帝。",
  "macedonian-dynasty:death": "「保加利亚人屠夫」（Βουλγαροκτόνος）巴西尔二世（Βασίλειος Βʹ）在位近五十年，于1025年12月15日去世。他没有选择葬在圣使徒教堂（Ἅγιοι Ἀπόστολοι）的历代皇帝之间，而是葬在城墙外赫布多蒙（Ἕβδομον）的神学家圣约翰教堂，就在他士兵的阅兵场旁。他的墓志铭写道：没有人见过我的长矛闲置。我守护着新罗马（Νέα Ῥώμη）的子民。他至死都是军人，愿长眠于军队集结之地。",
  // ——— Goths: siege … wedding ———
  "goths:siege": "408年秋，阿拉里克率领的哥特人封锁了罗马（Roma）的每一座城门，又截断了台伯河（Tiberis）上的驳船。城内先是断了面包，接着什么都没有了；罗马人派使者去问求和的代价。阿拉里克要全部的黄金、全部的白银和每一个外族奴隶。“那你还给我们留下什么？”使者问。“你们的性命。”他答道。最终罗马人付了钱，赎金里还有三千磅胡椒。",
  "goths:triumph": "公元500年，东哥特国王狄奥多里克为庆祝在位三十周年来到罗马。元老和民众出城迎接；他在圣彼得教堂祈祷，在广场上向人群讲话，承诺遵守旧日的法律。竞技场里举行了比赛，面包师向穷人分发粮食。对于曾在巴尔干流离失所的哥特人来说，这是一次回家——回到一座如今由他们守护的城市。",
  "goths:build": "想象：约520年的拉文纳。哥特和罗马工匠正在建造狄奥多里克的陵墓，一座用伊斯特拉白石砌成、不用灰浆的圆形建筑。最难的是屋顶：一整块穹顶形巨石，在海岸边凿成，再经亚得里亚海浮运过来。绳索穿过石上的提耳，土坡层层垒起，上百人随着一唱一和的号子缓缓拉动。巨石落定后，工头敲了敲它，笑了。",
  "goths:voyage": "史家约达尼斯本人有哥特血统，他在约551年写道，他的族人很久以前来自一座名叫斯堪扎的岛屿。在国王贝里格的带领下，他们只乘三条船渡海，登上一片海岸，称之为哥提斯堪扎。其中一条船比别的慢，他说，船上的人因此被称为格皮德人（Gepidae），这个名字来自一个意为“迟缓”的词。这是一个古老的故事，被远离故土的人们一遍遍讲述。",
  "goths:festival": "想象：一份六世纪在意大利抄写的哥特教会历书，把十一月称为 fruma Jiuleis（𐍆𐍂𐌿𐌼𐌰 𐌾𐌹𐌿𐌻𐌴𐌹𐍃），即尤尔节前的一个月。想象这个时节乡间的一户哥特人家：猪已宰好，啤酒已酿成，漫漫长夜里有故事，也有圆形里拉琴的琴声。信基督的哥特人唱着殉道者的节日圣歌，但那个表示仲冬的古老词语依然挂在每个人嘴边。",
  "goths:games": "罗马贵族西多尼乌斯·阿波利纳里斯约于455年在图卢兹（Tolosa）拜访西哥特国王狄奥多里克二世，并记下了国王的一天。午饭后，国王玩骰子和棋盘游戏。西多尼乌斯说，他掷得很快，赢了便说笑，输了也沉得住气；这正是求他办事的好时机，因为心情好的国王有求必应。桌边，哥特人和罗马人一同说笑、一同赌博。",
  "goths:drought": "在意大利的长期战争中，普罗科匹厄斯（Προκόπιος）记载，538年埃米利亚和皮切努姆的田地无人播种，随之而来的是一场可怕的饥荒。成千上万人死去；人们瘦得皮肤像干皮革，有人吃草和橡子。多年来，哥特农民和罗马农民都看着军队从自己的土地上开过。不论谁统治城镇，饥饿都落在同样的茅屋、同样的孩子身上。",
  "goths:quake": "想象：克里米亚山丘上的一处哥特聚落——在其他哥特人消失之后，这里的哥特人又延续了一千年。一个宁静的夏夜，大地晃动起来；陶罐从架上跌落，小石头教堂的一面墙裂开，狗在嚎叫。一家家人裹着毯子聚到屋外，神父用他们古老的语言领唱一首圣咏，直到大地重新平静。",
  "goths:winter": "想象：三世纪，黑海以北平原上的冬天。车营四周积雪没膝，牛瘦骨嶙峋，干草快要吃完。哥特妇女日夜守着车里的火，男人们骑马越过冰封的河流去打猎。夜里，骨笛吹着缓慢的曲调，老人们谈论着南方更温暖的土地。",
  "goths:plague": "542年，大瘟疫传到意大利，哥特人与查士丁尼（Ἰουστινιανός）的士兵已在这里交战七年。普罗科匹厄斯（Προκόπιος）写道，人们在发病前先看见鬼影，然后发烧，再后来腹股沟和腋下肿起。沿海的哥特村庄死了一半人。军队停战了一季，战争双方的家庭都在沉默中埋葬亲人。",
  "goths:wedding": "414年1月，在纳博讷（Narbo），哥特国王阿陶尔夫迎娶了罗马皇帝的妹妹加拉·普拉西提阿。她身着罗马皇家礼服端坐，他也穿着罗马服装，献给她五十名身着丝绸的俊美少年，每人捧着两只大盘，一盘盛满黄金，一盘盛满宝石。众人唱起婚礼之歌，哥特人和罗马人一同宴饮。有那么一刻，人们梦想两个民族可以合为一体。",

  // ——— Teutons: siege … wedding ———
  "teutons:siege": "1410年7月格伦瓦尔德战败之后，波兰和立陶宛大军向马林堡进发，那是骑士团在诺加特河畔的砖砌大要塞。未曾参加那场战役的指挥官海因里希·冯·普劳恩召集了几千名守军，烧掉城墙外的市镇，关闭了城门。八个星期里，大炮轰击城墙，痢疾在营地中蔓延，城堡却始终未破。九月，围城者撤走了。",
  "teutons:triumph": "十四世纪，条顿骑士团在柯尼斯堡设有“荣誉之桌”（Ehrentisch）。来自欧洲各地的骑士冬季征战归来时，城堡大厅里便摆开盛宴。最有资格的宾客坐在一张特设的桌旁，用银器进餐，传令官高声宣读他们的事迹。每人获得一枚徽章，上书“荣誉征服一切”（Honneur vainc tout）。号角齐鸣，吟游诗人歌唱着跨越冰原与森林的征途。",
  "teutons:build": "1309年，条顿骑士团大团长将驻地迁到马林堡，这座城堡逐渐成为欧洲最大的砖砌要塞。想象那时的工地：石灰窑冒着烟，一车车黏土从维斯瓦河（Wisła）草甸运来，制砖工把湿泥压进木模，巨大的踏轮起重机把重物吊上城墙。石匠和工人唱着歌打节拍，修士们在尘土中每天祈祷七次。",
  "teutons:voyage": "想象：春天，一艘满载琥珀、蜡和粮食的沉重柯克船驶离柯尼斯堡，开往布鲁日（Brugge）。骑士团的贸易总管检查过每一只木桶。数周里，船员沿着海岸航行，穿过松德海峡（Øresund），时刻提防风暴和海盗。后来某天早晨，雾散之后，桅顶的水手高喊：佛兰德（Vlaanderen）的塔楼！船员们唱起献给“海洋之星”圣母（Stella Maris）的赞美诗，驶向港口。",
  "teutons:festival": "想象：8月15日圣母升天节是条顿骑士团最盛大的节日，因为圣母是他们的主保。在马林堡，巨大的圣母像在城堡教堂上方熠熠生辉。修士们身披带黑十字的白色斗篷列队行进，村民从田间赶来，钟声齐鸣，唱诗班唱起《又圣母经》（Salve Regina）。弥撒之后，指挥官下令在城门口向穷人分发面包和啤酒。",
  "teutons:games": "想象：条顿骑士团的会规禁止修士参加比武和赌博，所以玩乐的是客人。在柯尼斯堡，来自英格兰、法兰西和莱茵兰（Rheinland）的来访骑士在出征前漫长的等待中比射箭、摔跤，在冰封的普雷格尔河上赛跑。修士们身披白色斗篷在城墙上观看。一位苏格兰骑士赢得了一只银杯，吟游诗人为此唱了一整个冬天。",
  "teutons:drought": "1315年至1317年，大雨毁掉了整个北欧的收成，史称大饥荒。在普鲁士，条顿骑士团在每座城堡都设有粮仓，粮价却依然飞涨。编年史家记载人们吃狗和草根，有人说还有更可怕的事。各地分团打开仓库，接济城门外的穷人，却永远不够。怀着沃土之梦东迁的农民明白了：饥饿也会远行。",
  "teutons:quake": "1202年5月20日，一场大地震撼动了叙利亚和圣地。在阿卡（عكا），年轻的条顿兄弟会在此设有医院，城墙开裂，房屋倒塌；在提尔（صور），城市大半坍塌。这些德意志修士当时更像护理者而非骑士，他们用担架把伤者抬进病房，在烛光下接骨。朝圣者写信回家说世界末日似乎临近，修士们却依旧唱着时辰祈祷。",
  "teutons:winter": "骑士团对立陶宛的征伐称为“远征”（Reisen），通常在隆冬进行，那时沼泽和河流冰封，军队可以走过夏天会陷下去的地方。骑士和客人们在冰雪严寒中连日穿越荒野。编年史记载，有的征伐因突如其来的解冻而全军覆没，也有的因严霜酷烈冻死了战马。围着篝火，修士们向圣母歌唱取暖。",
  "teutons:plague": "1349年和1350年，黑死病传到普鲁士。在城镇和骑士团的修道院里，修士们一个接一个病倒，整座会所空无一人。神父把死者埋进城墙外的长沟，丧钟响得太频繁，有些城镇干脆禁止鸣钟。在村庄里，普鲁士农民和德意志农民都紧闭门户。此后，骑士团不得不招募新的移民来耕种荒废的田地。",
  "teutons:wedding": "想象：骑士团的骑士立誓守贞、终身不婚，但他们的村庄却有婚礼。在普鲁士一个依库尔姆法建立的德意志移民村里，一位年轻农夫迎娶磨坊主的女儿。他们在教堂门口成婚，然后众人跟着一位提琴手和一位风笛手走到新娘家。指挥官送来一桶啤酒，舞一直跳到该挤牛奶的时候。",

  // ——— Germans: siege … wedding ———
  "germans:siege": "1628年夏，华伦斯坦的帝国军队围攻波罗的海贸易城市施特拉尔松德。据说他发誓，哪怕这座城被锁链拴在天上，他也要拿下它。市民——拿起火枪的商人和工匠——夜复一夜守卫城墙，大炮轰鸣，雨水灌满战壕。丹麦和瑞典的船只从海上送来援助。七月下旬，围城者撤走，施特拉尔松德至今仍以“华伦斯坦节”（Wallensteintage）纪念此事。",
  "germans:triumph": "1648年三十年战争（Dreißigjähriger Krieg）结束时，德意志各地城镇都举办了和平节。离家多年的士兵走回几乎认不出的村庄。1650年8月8日，奥格斯堡的路德宗信徒举行了“崇高和平节”（Hohes Friedensfest），有布道、圣歌和送给孩子们的礼物，这座城市至今仍把这一天定为节日。到处钟声齐鸣，人们唱着《众人今当谢主》（Nun danket alle Gott）。",
  "germans:build": "新的木桁架房屋骨架立起时，德国木匠要举行上梁节（Richtfest）。一棵小树或一个系着彩带的花环被升上最高的梁。木匠师傅穿着黑色灯芯绒衣服、戴着宽檐帽爬上去，朗诵上梁辞（Richtspruch）——为房屋和所有将住在里面的人祝福的韵文，喝下一杯酒，再把酒杯扔下摔碎。然后房主款待下面的所有人。",
  "germans:voyage": "1683年10月6日，“协和号”（Concord）在海上航行十多个星期后抵达费城。船上有十三户来自下莱茵（Niederrhein）克雷菲尔德的亚麻织工家庭，他们是门诺派和贵格会信徒，想找一个能安心守持信仰的地方。他们建立了日耳曼敦，五年后，那里的人写下了美洲最早的反奴隶制抗议书之一。每年的10月6日，当地都纪念这次航程结束的日子。",
  "germans:festival": "想象：十七世纪十二月的纽伦堡（Nürnberg）。圣婴市集（Christkindlesmarkt）挤满了圣母教堂下的主广场：木头摊位上卖着姜饼——用胡椒和蜂蜜调味的 Lebkuchen，还有木雕玩具、李子核桃做的小人和蜡烛。孩子们把脸贴在摊位上，号手在塔楼上吹奏众赞歌，烤杏仁的香气飘在寒冷的空气中。有那么几个星期，整座城市忘掉了债务和争吵。",
  "germans:games": "在德国各地，射手协会（Schützenvereine）每年夏天举办射手节（Schützenfest）。旧时的做法是在高杆上立一只木鸟，会员们用弩或火枪射击，直到最后一块碎片落下。射落它的人成为当年的“射手之王”（Schützenkönig），佩戴一条挂满奖章的沉重银链。随后乐队带领游行穿过街道，人人在啤酒帐篷里跳舞。",
  "germans:drought": "1816年是“无夏之年”，坦博拉火山喷发的火山灰遮暗了天空，整个夏天阴雨连绵，符腾堡和德国南部的庄稼烂在地里。面包价格涨了两倍，许多家庭变卖一切移民他乡。1818年终于迎来丰收，国王威廉一世在坎施塔特创立了丰收节，一根装饰着水果和谷物的柱子至今仍矗立在民俗节（Volksfest）的中心。",
  "germans:quake": "1756年2月18日，里斯本（Lisboa）地震几个月后，德国史上最强烈的地震袭击了莱茵兰（Rheinland）的迪伦附近。亚琛和科隆（Köln）的烟囱倒塌，教堂的钟自己响了起来，人们穿着睡衣逃到积雪的街上。传道人说这是上帝的警告，小册子详细描述了震动的情形。亲历过的孩子们后来会给孙辈讲那个钟声自鸣的早晨。",
  "germans:winter": "1573年严冬，博登湖（Bodensee）全湖封冻，当地称为 Seegfrörne。哈格瑙的人们踏冰把一尊福音书作者圣约翰的木雕胸像抬到瑞士岸边的明斯特林根，按照习俗，下次湖面封冻时必须把它送回来。1963年2月，湖又冻上了：成千上万人走过冰面，胸像在音乐和祈祷声中被抬回了家。",
  "germans:plague": "1633年，瘟疫传到巴伐利亚阿尔卑斯山（Bayerische Alpen）中的村庄上阿默高，几十人死去。村民立誓：若上帝饶恕他们，他们就每十年演出一次基督受难剧。传说立誓之后，再没有人死于瘟疫。1634年他们第一次在教堂墓地上、在死者的坟墓之上演出，这个村庄至今仍在演出，几乎家家户户都参加。",
  "germans:wedding": "1810年10月12日，巴伐利亚（Bayern）王储路德维希迎娶萨克森-希尔德堡豪森（Sachsen-Hildburghausen）的特蕾莎公主，慕尼黑（München）市民受邀一同庆祝。五天后，城门外的草地上举行了一场赛马，草地以新娘之名命名为特蕾莎草坪（Theresienwiese）。人人都玩得尽兴，第二年又办了一次，第三年也是。就这样，一场婚宴发展成了有铜管乐队、啤酒和舞蹈的慕尼黑啤酒节（Oktoberfest）。",

  // ——— Rhineland: siege … wedding ———
  "holy-roman-empire:siege": "1474年7月至1475年6月，勃艮第（Bourgogne）的大胆查理（Charles le Téméraire）率领庞大军队和当时最好的大炮围攻莱茵河（Rhein）畔的诺伊斯。城中守军不到四千人。他们夜里修补城墙，在敌人的壕沟下挖反地道，粮食吃完了就吃马。十一个月后援军到来，勃艮第人放弃了围攻。诺伊斯的钟声响了好几天。",
  "holy-roman-empire:triumph": "1164年7月23日，达瑟尔的赖纳尔德大主教（Rainald von Dassel）从意大利回到科隆（Köln），带回了东方三王（Heilige Drei Könige）的圣髑——就是那几位追随星光来到伯利恒的博士。全城出动迎接：神职人员手持蜡烛，行会成员举着旗帜，母亲们把孩子高高举起。每座教堂都敲响了钟。这些圣髑使科隆成为欧洲的朝圣大城之一，城徽上至今仍有三顶王冠。",
  "holy-roman-empire:build": "1248年8月15日，新科隆大教堂（Kölner Dom）奠基。石匠、石雕工和木匠一代又一代在这里劳作；约1560年资金耗尽，工程停止，一台巨大的木制起重机在未完工的南塔上矗立了将近四百年，成了城市天际线的一部分。1880年大教堂终于竣工，科隆以钟声、游行和持续数日的节庆来庆祝。",
  "holy-roman-empire:voyage": "想象：春天，一艘运酒船载着莱茵高的酒桶从美因茨开往科隆（Köln）。到了宾根，河道收窄，在礁石间奔涌，这就是危险的宾根洞（Binger Loch）；船夫们向圣尼古拉祈祷，用长篙撑船。驶过罗蕾莱（Loreley）峭壁时水流咆哮，最年长的船夫唱起歌来稳住年轻人的心。随后河面变宽，终于，科隆大教堂的起重机从晨雾中浮现。",
  "holy-roman-empire:festival": "自1349年起，亚琛每七年举行一次“圣物朝圣节”（Heiligtumsfahrt），展示圣物。朝圣者从低地诸国（Nederlanden）、匈牙利等地成千上万地涌来。当圣布从圣母教堂的廊台上展示时，人群吹起小陶号角（Aachhörner），直到全城回响。许多朝圣者在帽子上挂小镜子，以捕捉神圣的光芒，并把这份反光带回家去。",
  "holy-roman-empire:games": "1184年圣灵降临节，皇帝腓特烈·巴巴罗萨（Friedrich Barbarossa）在美因茨举行盛大的宫廷节庆，他的两个儿子在此受封为骑士。数万宾客在莱茵河（Rhein）草地上搭起丝绸帐篷宿营；有骑马比武、宴饮和歌唱，诗人们为此传颂了好几代。第二天，一场风暴刮倒了一座木教堂和几栋房屋，压死了一些宾客。人们说这是上天对骄傲过度的警示。",
  "holy-roman-empire:drought": "莱茵河（Rhein）及其邻近河流中有“饥饿石”（Hungersteine），只有河水极低时才会露出。在1540年那样的旱年，近十一个月几乎滴雨未下，人们就把年份刻在石上。河水低落意味着歉收、船只停航、没有粮食从上游运来。饥饿石一露头，莱茵兰人就知道饥荒近了。2018年炎热的夏天，它们又一次浮出了水面。",
  "holy-roman-empire:quake": "1356年10月18日圣路加节，一场大地震袭击了上莱茵（Oberrhein）的巴塞尔。最初的震动发生在晚饭时分，人们逃到了田野里。随后，打翻的炉灶引发大火，全城烧了好几天；大教堂的唱诗堂和塔楼倒塌。沿河几十座城堡受损。市民们重建家园，编年史家记下了这一天，让城市永不忘记。",
  "holy-roman-empire:winter": "想象：1408年的冬天在整个莱茵兰（Rheinland）被记作那个时代最冷的冬天之一。河水从岸到岸冻实；狼闯进了葡萄园，酒在桶里冻成冰，只能按块出售。解冻时，浮冰撞毁了桥梁和磨坊。在科隆（Köln），人们在冰封的莱茵河上溜冰，并在冰面破裂之前在上面开了集市。",
  "holy-roman-empire:plague": "1349年，黑死病席卷莱茵兰（Rheinland），一队队鞭笞派信徒从一个城镇走到另一个城镇。他们两人一排，唱着鞭笞者之歌（Geißlerlieder）前行，然后在集市广场上脱去上衣鞭打自己，相信自己的痛苦或许能平息上帝的怒火。市民们流着泪加入他们。不到一年，教会就禁止了这种游行，但他们的曲调被记录下来，流传至今。",
  "holy-roman-empire:wedding": "1235年夏，英格兰的伊莎贝拉溯莱茵河（Rhein）而上，前往沃尔姆斯嫁给皇帝腓特烈二世（Friedrich II.）。据马修·帕里斯（Matthaeus Parisiensis）记载，在科隆（Köln），一万名市民手持鲜花和树枝迎接她；还有些船仿佛在陆地上航行，由藏起来的马拉着，船上有神职人员在歌唱。她掀起面纱，好让妇女们看见她的脸。沃尔姆斯的婚宴持续了四天。",

  // ——— Transylvanian: siege … wedding ———
  "order-of-the-dragon:siege": "想象：布尔森兰（Burzenland）巴尔萨地区的萨克森村庄普雷日梅尔（Tartlau）没有城堡，只有一座设防教堂。一旦望见劫掠者，钟声便响起，家家户户跑进圆形围墙之内，每家都有一间编了号的小屋，四层叠起，各存一袋粮食。男人们从回廊上射击，女人们烧热水和沥青。他们一连数日等待，数着面包，直到劫掠者放弃离去。",
  "order-of-the-dragon:triumph": "想象：秋天，特兰西瓦尼亚的一座集镇。随督军（voievod）去多瑙河（Dunărea）的男人们沿着山谷的大路回来了，人数比出发时少。望见队伍时教堂钟声响起，母亲们在一张张脸中寻找。广场上，各行会举起旗帜，手摇弦琴和科博兹琴（koboz）奏起乐来，神父领唱《赞美颂》（Te Deum）。当晚有烤羊肉和李子白兰地（pălincă），失踪者的名字被轻声念起。",
  "order-of-the-dragon:build": "想象：十五世纪，萨克森葡萄酒村比尔坦（Birthälm）的村民在山顶教堂周围筑起第三道围墙。每户人家都要出工：男人用牛车把石头拉上山，女人运水和灰浆，石匠行会砌墙。一位木匠用木槌为抬梁的人打着节拍。门楼完工时，牧师为它祝福，人人都喝起了新酒。",
  "order-of-the-dragon:voyage": "十二世纪，匈牙利国王盖萨二世（II. Géza）邀请移民到王国空旷的东部边陲。来自莱茵河（Rhein）和摩泽尔河（Mosel）一带的家庭装满马车，横越欧洲走了几个月，他们后来被称为特兰西瓦尼亚萨克森人（Siebenbürger Sachsen）。想象最后一天：长长地翻越一座林木茂密的山口，然后脚下展开一片宽阔的山谷，河水闪着光。老人们摘下帽子：这里就是家了。",
  "order-of-the-dragon:festival": "每隔几年的狂欢节期间，萨克森小镇阿格尼塔（Agnetheln）都会举行“乌尔采尔奔跑”（Urzelnlauf）。年轻男子扮成乌尔采尔：身穿缀满流苏的蓬松黑衣，戴着狰狞面具，手持长鞭，在街上奔跑，甩响鞭子驱赶冬天、吓唬姑娘们。他们挨家挨户讨甜甜圈。据说这个习俗源于一个关于矿工的古老传说；那喧闹声是为了唤醒春天。",
  "order-of-the-dragon:games": "想象：布拉索夫（Kronstadt）的秋季大集市。在牲口市场和布匹摊之间，山里来的罗马尼亚年轻牧人在踩平的草地上摔跤，萨克森学徒用弩射靶，塞凯伊牧人沿着河边草地赛马。一位吹富卢亚笛（furulya）的人坐在木桶上，人群押上铜币打赌。摔跤冠军得到一只公羊，扛在肩上带回家。",
  "order-of-the-dragon:drought": "想象：特兰西瓦尼亚丘陵上一个干旱的夏天。溪流细成涓涓，玉米发黄，羊群被赶到高山上找草。罗马尼亚村庄里，姑娘们表演帕帕鲁达（Paparuda）：一个女孩只披绿叶，挨家挨户跳舞，妇女们把一桶桶水泼在她身上，唱歌求雨。老人们望着天空，一言不发。",
  "order-of-the-dragon:quake": "1802年10月26日，弗朗恰大地震撼动了喀尔巴阡山弯一带。在特兰西瓦尼亚（Ardeal）和瓦拉几亚（Țara Românească），教堂塔楼开裂倒塌，布加勒斯特（București）高耸的科尔恰塔也失去了塔顶。人们从屋里跑到秋天的田野上，跪在泥地里。神父敲响残存的钟。此后多年，人们用它来记年：大震之前，大震之后。",
  "order-of-the-dragon:winter": "想象：喀尔巴阡山村的隆冬。积雪埋到屋檐；狼从森林里下来，夜里围着羊圈打转。牧人们已把羊群赶回家，漫长的夜晚里刻木勺、吹富卢亚笛（furulya）。当大雪封住通往布拉索夫的山口，村子就靠熏咸肉、奶酪和玉米面过活。平安夜，男孩们踏着雪堆挨家挨户去唱颂歌。",
  "order-of-the-dragon:plague": "想象：1495年，瘟疫传到锡比乌（Hermannstadt）。市议会关闭城门，焚烧死者的被褥，并出钱留住一位理发外科医生。有钱的商人逃到自家葡萄园去。教堂里，人们向圣塞巴斯蒂安和圣洛克祈祷，丧钟为死者不停地响，直到议会下令停敲，以免吓坏活着的人。瘟疫过去后，各行会举行游行感恩。",
  "order-of-the-dragon:wedding": "想象：特兰西瓦尼亚村庄里的一场萨克森婚礼。婚礼当天，新娘最后一次戴上博尔滕（Borten）——一顶缀着长丝带的高筒黑天鹅绒冠，因为已婚妇女要把头发遮起来。邻里互助会（Nachbarschaft）一起准备宴席，全村人跟着乐手走向教堂。誓约之后，博尔滕被取下，换上已婚妇女的头纱，舞蹈开始了。",

  // ——— Norse: siege … wedding ———
  "vikings:siege": "885年11月，一支据说有数百艘船的诺斯大舰队溯塞纳河而上，围攻巴黎。将近一年里，诺斯人用攻城槌、火船和投石机攻打桥梁和塔楼。冬天来了，疾病在他们营中蔓延，城市却依然坚守。修士阿博为此写了一首诗。最终，诺斯人收了钱，前往上游的勃艮第（Bourgogne），把船从陆路拖着绕过了城市。",
  "vikings:triumph": "想象：秋天，船队绕过岬角驶回峡湾。岸上全农庄的人都在等候；船桨扬起时，孩子们沿着海滩奔跑。当晚大厅里设宴：众人饮下首领的誓杯（bragarfull），男人们站上长凳夸耀功绩，吟唱诗人（skald）朗诵一首新作，颂扬这次远航。银臂环被分赏下去。死去的人也被举杯纪念。",
  "vikings:build": "想象：冬天，韦斯特福尔的一座农庄。造船匠和他的人用楔子把长长的橡木劈成薄板，从不用锯，好让木纹完整贯通。他们一列接一列铆接船壳，每块板相互搭叠，再用浸了焦油的羊毛填缝。年轻人踩着在蒸汽中弯曲的木料；一位老人唱着一首关于大海的歌打节拍。到了春天，船已架在滚木上，整装待发。",
  "vikings:voyage": "《定居者之书》（Landnámabók）讲述了弗洛基·维尔格达尔松的故事：他从挪威向西航行，去寻找被风暴吹偏的水手们见过的一片土地。他带了三只渡鸦。第一只飞回了挪威，第二只盘旋一圈又回到船上，第三只却径直向前飞去，弗洛基跟着它找到了陆地。他因峡湾里的浮冰把它叫作冰岛（Ísland），从此人称“渡鸦弗洛基”（Hrafna-Flóki）。",
  "vikings:festival": "尤尔节（Jól）是诺斯人盛大的仲冬节日。萨迦记载，农民们把麦酒和牲畜带到神庙，用祭牲的血洒在墙上；人们举杯敬奥丁（ᚢᚦᛁᚾ）求胜利，敬尼约德和弗雷求丰年与和平。然后连续宴饮三夜。信奉基督教的“善良者”哈康国王把这个节日移到了圣诞节，但 jól 这个名字留了下来。",
  "vikings:games": "萨迦描述，在冰岛的大议会阿尔庭（Alþingi）上，人们在冰面上用球棒和硬球进行两队对抗的球赛（knattleikr），往往激烈到有人受伤、结下世仇。还有斗马——让两匹种马相斗，有名为格利玛（glíma）的摔跤、游泳比赛，以及为奖品而吟诵的吟唱诗。年轻人来这里既为法律，也同样为了比赛。",
  "vikings:drought": "《定居者之书》和编年史记载了冰岛（Ísland）约976年的饥荒之冬，那是早期定居时最惨的一次。草长不出来，牛死在栏里，人们找到什么吃什么：海鸟、海藻，甚至渡鸦和狐狸。据说有些老人被留下等死，好让年轻人活下去。幸存者把那段时间称为“大匮乏之冬”（óaldarvetr），代代相传。",
  "vikings:quake": "约1104年，海克拉火山自人类来到冰岛（Ísland）以来首次喷发。浮石和火山灰如暴雨般落在肖尔斯河谷（Þjórsárdalur），农民们曾在那里的白桦林间建起草皮屋。各家带着能带走的东西逃离；斯通农庄被掩埋、废弃。后来的冰岛人相信海克拉的火山口是地狱之门，它的隆隆声令他们恐惧。",
  "vikings:winter": "想象：约1300年，格陵兰（Grænland）诺斯人定居点的冬天。太阳几乎不升起；牛羊从秋天起就关在圈里，干草快吃完了。男人们到冰上猎海豹，女人们在皂石灯下纺线。黑暗中，老人们讲起芬布尔之冬（Fimbulvetr）——世界末日之前那长达三年的大寒冬，孩子们听得睁大了眼睛。",
  "vikings:plague": "1349年，一艘英格兰船驶入卑尔根港，载着羊毛，也载来了黑死病。冰岛编年史说，全船船员都死了，疾病很快传遍全城，又沿着每一条峡湾蔓延开去。偏远山谷里的农庄空无一人，税册显示土地荒芜了好几代。在挪威传说中，瘟疫是一个名叫佩斯塔（Pesta）的老妇人，手持耙子和扫帚：她用耙子耙过的地方，还有人活下来；她用扫帚扫过的地方，无一幸存。",
  "vikings:wedding": "诺斯人的婚礼叫作 brúðhlaup，意为“新娘之奔”，是一场持续数日的盛宴。新娘披散头发，戴着新娘冠，新郎有时佩着祖先的剑。诗歌《索列姆之歌》（Þrymskviða）说，人们把索尔（ᚦᚢᚱ）的锤子放在新娘膝上为她祝圣。宾客们喝新娘麦酒，新人共饮一杯。最后，新娘把头发挽起，罩上已婚妇女的亚麻头巾。",

  // ——— Swedes: siege … wedding ———
  "swedes:siege": "1715年秋，国王卡尔十二世（Karl XII）亲自坐镇的施特拉尔松德瑞典守军被一支庞大的联军围困。寒冷的几个月里，大炮轰塌城墙，外围的吕根岛也失守了。士兵们吃马肉和硬面包，国王穿着靴子睡觉。12月22日夜里，他乘一条小船穿过冰层悄悄返回瑞典；第二天，城市投降。",
  "swedes:triumph": "1631年9月，消息传到斯德哥尔摩：瑞典军队在德意志的布赖滕费尔德打了一场大胜仗。全国教堂钟声齐鸣，每个教区都唱起《赞美颂》（Te Deum），山头燃起篝火。按征兵名册把儿子送往南方的母亲们盼着战争结束、孩子回家。有些人多年后确实回来了，长得高大，饱经风霜，带回家乡人无法想象的故事。",
  "swedes:build": "1626年至1628年，在斯德哥尔摩的海军船厂，约四百名工人建造了战舰“瓦萨号”（Vasa）：木匠、锯工、铁匠、玻璃匠、画匠，还有为她装饰数百座镀金雕像的木雕师。1628年8月10日，她在岸上人群的注视下开始处女航。一阵风吹得船身倾斜，海水从炮门涌入，她在城市的视线之内沉没了。1961年，她被重新打捞出水。",
  "swedes:voyage": "1637年末，“卡尔马钥匙号”（Kalmar Nyckel）和“鸟鹫号”（Fogel Grip）载着瑞典和芬兰的移民——士兵和农民——从哥德堡（Göteborg）启航前往美洲。经过漫长的冬季航行，1638年3月，他们溯特拉华河而上，在一处岩岬登陆，以克里斯蒂娜女王（Kristina）的名字为它命名。他们在这里建立了新瑞典（Nya Sverige）。芬兰移民带来了原木小屋，它后来传遍了美洲的边疆。",
  "swedes:festival": "仲夏节（midsommar）时，瑞典人竖起仲夏柱（midsommarstång），这是一根缠满桦叶和野花的高杆，横梁上挂着两个花环。提琴手和尼克尔哈帕琴（nyckelharpa）手领着大家绕柱跳舞，人人都跳起“小青蛙舞”（små grodorna），边跳边呱呱叫。姑娘们采七种花放在枕下入睡，好梦见将来要嫁的人。明亮的夜晚始终不会真正暗下来。",
  "swedes:games": "传说1520年至1521年冬，年轻的古斯塔夫·埃里克松·瓦萨从莫拉踏着滑雪板向挪威逃去，两个莫拉人滑雪追上他，请他回来领导起义。自1922年起，每年三月都有成千上万名滑雪者在瓦萨越野滑雪赛（Vasaloppet）中重走这条路线，穿越达拉纳的森林，全程九十公里。沿途志愿者分发热腾腾的蓝莓汤（blåbärssoppa），莫拉的终点满是音乐。",
  "swedes:drought": "1695年至1697年，一连几个寒冷多雨的夏天给瑞典、尤其是芬兰带来了大饥荒（den stora svälten）。庄稼年年歉收。人们用松树皮掺着稻草和谷糠烤成树皮面包（barkbröd），乞丐挤满了道路。芬兰大约三分之一的人口死去。教区神父在登记簿上写下长长的下葬名单，有些人还在末尾添上一行祷文。",
  "swedes:winter": "1658年冬是人们记忆中最冷的冬天，丹麦诸岛之间的海面冻住了。一月和二月，国王卡尔十世·古斯塔夫（Karl X Gustav）率军步行和骑马越过小贝尔特海峡（Lillebælt）和大贝尔特海峡（Storebælt）的冰面。有一处冰层破裂，两个骑兵中队落入水中。士兵们彼此隔开、小心前行，听着脚下的冰在呻吟。他们抵达了对岸，几周之内战争便结束了。",
  "swedes:plague": "1710年，瘟疫传到斯德哥尔摩。随着它在狭窄的巷子里蔓延，宫廷和富人逃往乡间，城里除了运尸车的声响一片寂静。几个月内，斯德哥尔摩或许有三分之一的人死去。神父在城外挖好的长沟旁诵读葬礼经文。留下来的穷人互相照料，瘟疫终于离去时，幸存者唱起了圣诗。",
  "swedes:wedding": "想象：达拉纳的一场农家婚礼。新娘戴着教区的银质新娘冠（brudkrona），这是教堂借给她用一天的。提琴手们（spelmän）奏着新娘进行曲（brudmarsch）领着队伍走向教堂，每个村子都有自己的版本。礼拜之后，宴席持续三天，谷仓里跳舞，咖啡喝个没完。最后一夜，新娘的冠冕被取下，她以少女的身份跳最后一支舞。",

  // ——— Lithuanians: siege … wedding ———
  "lithuanians:siege": "1336年2月，一支十字军围攻涅曼河畔的木制山堡皮列奈（Pilėnai），约四千名立陶宛人在此避难。守军看到城墙守不住了，便点起一场大火，烧掉了自己的财物；据编年史记载，他们宁愿一同葬身火海，也不愿被俘。据说他们的首领马尔吉里斯（Margiris）是最后一个。从此，立陶宛人一直传颂着皮列奈的故事。",
  "lithuanians:triumph": "想象：夏末，战士们沿河回到村庄。妇女们一直在山上眺望，这时唱着歌跑下山来，老人们打开一桶桶啤酒（alus）和蜂蜜酒（midus）。当晚院子里设宴。人们拿出康克列琴（kanklės），妇女们唱起苏塔尔蒂内（sutartinės）——声部交织的古老歌谣，唱天鹅，唱橡树。阵亡者的名字也被唱了出来。",
  "lithuanians:build": "传说大公格迪米纳斯打了一天猎后，在涅里斯河与维尔尼亚河的交汇处过夜。他梦见一只铁狼在山上嚎叫，发出上百只狼的声音。异教祭司利兹德伊卡告诉他，这个梦的意思是他应当在那里建一座城堡和一座城市，它的名声将响彻世界。于是约在1323年，人们开始在山上建造维尔纽斯。",
  "lithuanians:voyage": "想象：春天冰融之后，放排人（sielininkai）把巨大的松木木排顺涅曼河而下，漂向克莱佩达的大海。这段旅程要走好几个星期。他们住在木排上的小棚里，在铺了泥土的火塘上做饭，在河湾处用篙撑着木排转弯。夜里，他们唱着思念家乡、思念等候的姑娘的长歌。后来河面变宽，海鸥出现，他们闻到了大海的气息。",
  "lithuanians:festival": "在一年中最短的夜晚——拉索斯节（Rasos），又称约尼内斯节（Joninės）——立陶宛人聚在河边湖畔。姑娘们用野花编成花环，插上蜡烛放到水上漂；若两个花环漂到一起，这对人就会成婚。年轻人跳过篝火，走进森林寻找蕨花，据说它只在这一夜开放，找到的人会交好运。歌声在水面上回荡，直到黎明。",
  "lithuanians:games": "复活节（Velykos）时，立陶宛孩子们玩滚彩蛋（kiaušinių ridinėjimas）。每人带一篮用洋葱皮染色、刻着花纹的鸡蛋。蛋一个接一个从木槽里滚下；谁的蛋撞到别人的蛋，就把那个蛋赢走。大一些的男孩互相碰蛋，看谁的蛋壳最硬。年轻人在村里搭起的大秋千（supynės）上荡来荡去，据说荡得越高，亚麻就长得越高。",
  "lithuanians:drought": "想象：古立陶宛土地上一个干旱的夏天。黑麦长得矮小，牛也瘦了。村民们到神圣的橡树下向雷神佩尔库纳斯（Perkūnas）祈祷，一位老妇人把啤酒浇在树根上。年轻人用河水互相泼洒，好让天空看见、照着去做。每天傍晚，一家家人坐在屋外，倾听西边传来的第一声雷鸣。",
  "lithuanians:winter": "想象：隆冬时节的立陶宛农舍。雪深得邻居之间只能踩着滑雪板往来。漫长的夜晚，一家人围坐在炉边：女人纺亚麻、唱歌，男人刻木勺、修马具。平安夜（Kūčios），十二道素菜摆在铺着干草的桌布上，还为家中的亡者留出一个座位。屋外，狼在森林边上嚎叫。",
  "lithuanians:plague": "1709年至1711年，在一个可怕的寒冬和军队过境之后，瘟疫席卷了立陶宛和普鲁士。有些地区一半以上的人死去；整座整座的村庄空无一人，田地重新长成森林。幸存者把死者葬在远离村庄的瘟疫墓地，并立起木十字架。在许多地方，这些古老的瘟疫墓（maro kapeliai）至今仍被人们记得和照料。",
  "lithuanians:wedding": "立陶宛婚礼是一出漫长的歌之戏剧。媒人（piršlys）夸赞新郎，却遭到新娘家人的嘲弄。婚礼前夕，新娘的伴娘们唱着哀伤的歌，摘下她象征少女身份的芸香花环（rūtų vainikas）。新娘唱起哭嫁歌（raudos），告别母亲的家。随后新郎一行到来，宴席以面包、盐和啤酒开始。",

  // ——— Poles: siege … wedding ———
  "poles:siege": "1655年11月至12月，一支瑞典军队围攻琴斯托霍瓦的光明山（Jasna Góra）修道院。院内只有约七十名修士和几百名士兵与市民，还有黑圣母（Czarna Madonna）圣像。院长奥古斯丁·科尔德茨基（Augustyn Kordecki）在炮火间隙带领众人祈祷，城墙守住了。四十天后瑞典人撤退。人们说是圣母亲自守护了她的殿堂，这个故事传遍了全国。",
  "poles:triumph": "想象：1683年末，维也纳（Wien）解围之后，翼骑兵骑马经过克拉科夫回家。他们羽翼沙沙作响；身后跟着满载缴获的帐篷、地毯和一袋袋奇怪豆子的大车，没人知道这些豆子怎么煮。人群夹道，圣母圣殿（Mariacki）的钟声响起，塔楼上的号手吹起报时号曲（hejnał）。士兵们在人群中找到了家人，而那些豆子原来是咖啡。",
  "poles:build": "在维利奇卡盐矿深处，矿工们用岩盐雕出了一座教堂。圣金加礼拜堂（Kaplica św. Kingi）由矿工们从1896年起利用业余时间开凿，历时近七十年：墙壁、地面、祭坛和浮雕，连吊灯都是用盐晶做的。每天在黑暗中劳作的矿工们，为自己造了一处明亮的祈祷之所；在他们的主保圣人节——圣芭芭拉节（Barbórka），他们至今仍在那里歌唱。",
  "poles:voyage": "想象：春天，维斯瓦河的放排人（flisacy）把满载粮食的木排从克拉科夫顺维斯瓦河（Wisła）而下，漂向格但斯克，一路要走好几个星期。他们睡在木排上的草棚里，用长桨掌舵，唱着放排人之歌。到了托伦，他们歇脚喝酒；之后河面变宽、水流变缓。终于，格但斯克的塔楼和起重机出现在前方，船只正等着把粮食运往阿姆斯特丹。",
  "poles:festival": "收获结束时，波兰村庄要庆祝丰收节（dożynki）。姑娘们用最后的麦穗编成一个大花环，饰以鲜花、苹果和丝带，唱着歌列队把它送到庄园和教堂。农户或领主接过花环，回赠一场有面包、啤酒和舞蹈的宴会。留在地里的最后一捆庄稼叫作“胡子”（broda），据说寄宿着丰收之灵。",
  "poles:games": "自十三世纪起，克拉科夫的射鸡兄弟会（Bractwo Kurkowe）每年夏天举办射击比赛。靶子是一只立在高杆上的木公鸡（kurek）。射落它的人成为当年的“射鸡之王”，佩戴“银公鸡”（Srebrny Kur）——一只1565年制作的、镶嵌珠宝的公鸡形高脚杯。他骑马在城中游行，兄弟会成员身着古装随行，随后大摆宴席。",
  "poles:drought": "想象：马佐夫舍（Mazowsze）村庄里一个干旱的夏天。黑麦秆短小发白，井水低落，奶牛产奶很少。妇女们列队走到路边神龛，捧着圣像唱圣母颂歌，神父用圣水为田地祝福。傍晚，老人们坐在屋外的长凳上望着西边，说：上帝在等我们学会忍耐。",
  "poles:winter": "想象：塔特拉山区波德哈莱（Podhale）的冬天。雪积到扎科帕内木屋的窗户。山民（górale）把羊关在棚里，日夜烧着云杉木柴。漫长的夜晚，提琴手带着他们的苏卡琴（suka）来到炉边演奏，女人们在一旁刺绣。平安夜（Wigilia），一家人等待第一颗星出现，然后掰开圣饼（opłatek），共享晚餐。",
  "poles:plague": "想象：夏天，瘟疫来到克拉科夫。富人逃往乡下，大学关闭。市议会雇来掘墓人，在城墙外设立隔离病院。教堂里，人们在圣洛克像前祈祷，巨大的齐格蒙特钟（Dzwon Zygmunta）为全城鸣响。秋天瘟疫终于过去时，市民们赤脚列队走向瓦维尔主教座堂感恩。",
  "poles:wedding": "在波兰的乡村婚礼（wesele）上，高潮在午夜到来：戴帽礼（oczepiny）。新娘头上的少女花环被取下，已婚妇女们给她戴上妻子的头帽（czepiec），一边唱着她的少女时代已经结束。按规矩她要推拒、哭泣，年轻人则唱着既伤感又逗趣的歌。随后她和每位宾客跳舞，婚礼一连持续好几天。",

  // ——— Bohemians: siege … wedding ———
  "bohemians:siege": "1422年5月至11月，胡斯派军队围攻了卡尔施泰因（Karlštejn）王城，那里曾经收藏过王冠珠宝。数百人的守军据守悬崖，石弹和投石机不断轰击城墙。编年史记载，围攻者甚至把一桶桶污秽和死者的尸体抛进城内，想要散播疾病。守军喝石灰水抵御疾病，坚持不降，围攻者最后只得回家。",
  "bohemians:triumph": "想象：1431年秋。十字军在多马日利采（Domažlice）溃逃之后，胡斯派野战军回到塔波尔（Tábor）。战车排成长龙驶进城来，车夫们唱着《你们这些上帝的战士》（Ktož jsú boží bojovníci）。妇女和孩子们拿着面包和啤酒跑出来迎接。广场上，神父按照胡斯派认为正确的方式，向所有人施行饼酒同领的圣餐，全城一同歌唱。",
  "bohemians:build": "1344年，布拉格城堡（Pražský hrad）的圣维特大教堂（svatý Vít）开工兴建。第一位工匠师傅去世后，年轻的彼得·帕尔勒（Petr Parléř）于1356年从施瓦本（Schwaben）来到这里，主持工程长达数十年。他手下的石匠、木匠和玻璃匠建起了一座轻盈得仿佛悬浮空中的石砌唱诗堂，交错肋拱组成的网状拱顶前所未见。帕尔勒还把自己的面容刻进了廊台上的人像之中。",
  "bohemians:voyage": "1628年，成千上万的波希米亚新教徒被迫离开故土，其中就有教师扬·阿莫斯·夸美纽斯（Jan Amos Komenský），他属于弟兄合一会（Jednota bratrská）。相传在边境的山岗上，流亡者们回望自己深爱的土地，跪下祈祷，夸美纽斯祈求上帝在那里保留他们信仰的一粒种子。随后他们继续走向莱什诺（Leszno），除了赞美诗集，几乎一无所有。",
  "bohemians:festival": "捷克狂欢节「马索普斯特」（Masopust）在大斋期之前举行。戴面具的人物在村里游行：拴着链子的熊、穿裙子的马、烟囱清扫工、提着一篮鸡蛋的女人、土耳其人，还有裹着稻草的人。他们挨家挨户讨要甜甜圈（koblihy）和腌肉，乐队一路演奏。午夜时分，人们为低音提琴举行一场假葬礼，斋期就此开始。",
  "bohemians:games": "想象：南波希米亚一个周日的下午，在村中小酒馆（hospoda）后面。年轻人在长长的木道上玩九柱球（kuželky），一个男孩跑来跑去摆好木柱、把球滚回来。老人们用粉笔在木板上记分，大声争论。屋里，一位风笛手（dudy）和一位提琴手正为晚上的舞会热身。赢家请大家喝一轮啤酒，输家得唱一首歌。",
  "bohemians:drought": "在杰钦（Děčín）的易北河（Labe）岸边，有一块饥饿石（hladový kámen），只有在干旱之年才会露出水面。石上刻着历次旱年的年份，还有一句德语：「Wenn du mich siehst, dann weine」——看到我时，你就哭吧。河水低落意味着歉收和昂贵的面包。2018年炎热的夏天，这块石头再次露出水面，人们成群赶来观看，随即陷入沉默。",
  "bohemians:quake": "在波希米亚最西端的海布（Cheb）一带，大地会成群地震动：几周之内发生数百次小地震，震源深藏在卡罗维发利（Karlovy Vary）和弗朗季什科维温泉镇（Františkovy Lázně）这些古老温泉小镇的地下。想象：在这样的一个冬天，村民们夜里一次又一次听见窗户咯咯作响，矿泉水的泉眼也冒得更欢了。老妇人们在胸前画十字，温泉医生们做着笔记，谁也说不清该害怕还是该自豪。",
  "bohemians:winter": "想象：克尔科诺谢山（Krkonoše），即巨人山的冬天。大雪把木屋一直埋到屋顶，山间小屋的人们挖出通往谷仓的雪道。男人们踩着长长的木制滑雪板出门取柴和食物。晚上，一家人在炉边做玻璃珠或织亚麻布，老人们讲起山神克拉科诺什（Krakonoš）的故事：他惩罚贪婪的人，帮助在雪中迷路的老实人。",
  "bohemians:plague": "1713年，瘟疫袭击了银矿之城库特纳霍拉（Kutná Hora），这是波希米亚最后一次大瘟疫。城市恢复元气后，居民们立起一根瘟疫纪念柱（morový sloup），柱上布满圣徒和天使，顶端立着圣母像，感谢疾病终于过去。柱子由耶稣会雕塑家弗朗齐歇克·鲍古特（František Baugut）雕刻，至今仍矗立在广场上。每年市民们都会聚集在柱旁，唱一首赞美诗纪念逝者。",
  "bohemians:wedding": "想象：霍德地区（Chodsko）一个波希米亚村庄的婚礼。送亲队伍跟着风笛手（dudák）走向教堂，他的风笛（dudy）上装饰着山羊头。新娘戴着迷迭香和缎带编成的花环；按照习俗，她的母亲在门口哭泣。从教堂回来后，宾客们吃面条汤、烤猪肉和果馅小圆饼（koláče）。午夜时分，新娘的花环被摘下，换上已婚妇女的软帽（čepec），众人齐声歌唱。",

  // ——— Slavs: siege … wedding ———
  "slavs:siege": "据弗雷德加编年史（Fredegarius）记载，631年，法兰克国王达戈贝尔特派兵攻打由萨莫统治的斯拉夫人，萨莫原是一名商人，后来成了他们的首领。斯拉夫人聚集在沃加斯蒂斯堡（Wogastisburg）要塞中，抵挡了三天的进攻。第三天他们冲出城来，把法兰克人赶跑，敌人连帐篷都丢下了。这个地方至今没有找到，但斯拉夫人记住了他们曾经团结一致。",
  "slavs:triumph": "想象：战士们从多瑙河以南渡河归来，带回了马匹、牛群和白银。全村人都到渡口迎接。妇女们烤起圆面包（karavai），男人们宰了一头公牛，为祭祀佩伦（Перунъ）的宴会做准备。古斯里琴（гусли）琴手歌唱渡河与归乡。篝火燃尽时，年轻人围成圆圈跳起轮舞（хороводъ），一直跳到天亮。",
  "slavs:build": "想象：河边的山丘上，一座斯拉夫城寨（градъ）拔地而起。整个氏族干了一整个夏天：男人砍伐橡树，把原木交叉叠成木箱，妇女和孩子搬来泥土和石块填满。城墙越垒越高，超过一人，再超过两人。墙顶插上一排削尖的木桩。城门装好时，长老在门槛上杀一只公鸡，洒下鸡血以求吉利。",
  "slavs:voyage": "想象：六世纪。一个斯拉夫氏族决定南迁，追随其他人渡过多瑙河。他们把工具、种粮和小孩装进独木舟（μονόξυλα），顺流而下，牛群在后面游着跟随。每晚他们在岸边扎营。许多天之后，一片新土地的山丘出现在眼前，青翠而空旷。长老踏上岸，跪下亲吻大地。",
  "slavs:festival": "一年中最短的夜晚，即库帕拉之夜（Купала），斯拉夫青年聚集在河边。他们点燃巨大的篝火，两人一对手牵手跳过火堆；如果两人没有松手，就会结为夫妻。姑娘们把插着蜡烛的花环放到水上漂走，以占卜命运。年轻人到林中寻找蕨花，据说它只在这一夜开放，谁找到就会交好运。",
  "slavs:games": "想象：在城寨旁的夏日节庆上，斯拉夫青年们比试身手。他们在草地上摔跤，沿着河边草甸赛马，比谁能把最重的石头扔得最远。姑娘们在河岸上观看，把鲜花编进辫子。摔跤冠军从长老手中接过一杯蜂蜜酒，古多克琴（гудок）琴手当场为他编一首歌，一半赞美，一半调侃。",
  "slavs:drought": "想象：天空已经好几周没有一丝云彩，黍子都枯萎了。村里的妇女们挑选一个孤女，从头到脚给她裹上绿叶和青草。她就是多多拉（додола）。她挨家挨户跳舞，妇女们唱着「Oj dodo, oj dodole」（Ој додо, ој додоле），向上天祈雨；每到一家门口，女主人就往她身上泼水。孩子们跟在后面，在尘土里踩水嬉闹。",
  "slavs:winter": "想象：森林地带漫长的冬天。积雪从秋天一直留到春天，河面冻得厚厚的，地窖里的粮食越来越少。一家人守在半地穴式的房子里，围着炉火过冬。仲冬时节，年轻人戴上面具过科利亚达节（Колѧда），在每家门口唱歌，讨要面包和祝福。老人们讲起冬之女神莫拉娜（Морана）的故事：春天来时，她将被投入河中淹没。",
  "slavs:plague": "想象：六世纪的大瘟疫沿着罗马世界的道路传播，抵达了多瑙河畔的斯拉夫村庄。一家接一家的人病倒；死者按照习俗火化，骨灰装进陶瓮。幸存者离开村子，在森林的另一边建起新村，好让疾病追不上他们。他们一边离开，一边唱着哀歌。",
  "slavs:wedding": "约成书于1113年的《往年纪事》（Повѣсть времѧньныхъ лѣтъ）记载了早期斯拉夫人的婚俗。书中说，在波利安人（Полѧне）中，新郎并不亲自去接新娘，而是在晚上把新娘送到他那里，嫁妆第二天再送来。在其他部落中，年轻人在村与村之间的游戏聚会上相会，唱歌跳舞，每个男人带走与他事先说好的女子。",

  // ——— Rus: siege … wedding ———
  "rus:siege": "1238年，拔都（Бату）率领的蒙古军来到森林中的小城科泽利斯克（Козельскъ）。当时城中的王公只是一个大约十二岁的男孩。市民拒绝投降，在木城墙后坚守了七个星期，比其他任何城市都久。编年史说，当蒙古人终于攻入城中时，守军拿着刀冲出去战斗。蒙古人称科泽利斯克为「恶城」，而罗斯人则把它记作不肯低头的城市。",
  "rus:triumph": "《伊戈尔远征记》（Слово о плъку Игоревѣ）以归乡作结。伊戈尔（Игорь）王公在草原上战败被俘，后来逃脱，骑马穿越平原回家。诗人写道：太阳照耀在天空，伊戈尔王公回到了罗斯大地；少女们在多瑙河边歌唱，歌声越过大海传到基辅（Кыѥвъ）。伊戈尔骑马前往圣母教堂，城镇和村庄一片欢腾。",
  "rus:build": "在诺夫哥罗德（Новъгородъ），街道是用木头铺成的。每隔二三十年，旧原木就会陷进潮湿的地里，市民们便在旧路面上铺一层新的：把劈开的松木横放在长长的纵木上。每条街由所在街区出钱修建。考古学家发现了二十多层叠在一起的路面，层间还散落着桦树皮文书（берестяныя грамоты），其中一封是父亲提醒儿子把鞋子带回家。",
  "rus:voyage": "约950年，君士坦丁七世（Κωνσταντῖνος Ζʹ）记述了罗斯人每年六月如何乘独木舟沿第聂伯河（Днѣпръ）南下，到君士坦丁堡（Κωνσταντινούπολις）做买卖。到了险滩处，他们卸下奴隶和货物，把船拖过或抬过险滩。其中一处险滩叫埃苏皮（Ἐσσουπῆ），意思是「别睡觉」。过了险滩，在圣格里高利岛上，他们在一棵大橡树下献祭活公鸡以示感恩。随后大海便在眼前展开。",
  "rus:festival": "谢肉节（Масленица）是大斋期前的黄油周，也是罗斯人最欢乐的节日。每天人们都吃布林饼（блины），这种薄饼像太阳一样又圆又金黄，配上黄油、酸奶油和蜂蜜。有雪橇游、雪堡大战，还有冰上的拳斗。最后一天是宽恕星期日，人们互相请求原谅，把象征冬天的草人投进篝火焚烧，众人一齐歌唱。",
  "rus:games": "想象：一个冬日的星期天，在城下结冰的河面上，两个街区的年轻人面对面展开「墙对墙」拳斗（стенка）。规矩很严：不许带武器，不许打倒地的人，不许打腰带以下。先是男孩们上场，接着是青年，最后是最强壮的汉子。人群在岸上欢呼。比完之后，双方一起到酒馆喝酒。",
  "rus:drought": "《诺夫哥罗德编年史》（Новгородская летопись）记载，1230年是可怕的饥荒之年。霜冻冻死了庄稼，粮价飞涨，没人买得起。人们吃苔藓、松树皮、椴树叶，吃猫吃狗；编年史家说，甚至还有更糟的事。尸体横陈街头，被狗吞食。大主教修建了一座公共墓坑（скудельница），里面埋了数千人。有些人家把孩子卖给商人，好让他们活下去。",
  "rus:winter": "想象：弗拉基米尔（Владимиръ）附近一个村庄的漫长冬天。积雪把木屋埋到窗口；炉子日夜燃烧，一家人就睡在炉顶上。男人们在河面上凿冰窟窿捕鱼，赶着雪橇去森林拉柴。妇女们借着松明（лучина）的光纺亚麻、唱歌。夜里狼群逼近，狗对着黑暗狂吠。",
  "rus:plague": "1352年，黑死病传到普斯科夫（Пльсковъ）。编年史说，市民死得太快，神父们来不及埋葬；每天夜里，他们都要把五具或十具尸体放进同一个墓穴。许多人把全部家产捐给教堂和修道院。编年史还说，在格卢霍夫（Глуховъ）城，竟没有一个人活下来。普斯科夫派人请诺夫哥罗德（Новъгородъ）大主教前来为城市祝福，他来了。",
  "rus:wedding": "988年，基辅（Кыѥвъ）大公弗拉基米尔（Владимиръ）受洗，并在克里米亚的赫尔松涅斯（Χερσόνησος）迎娶了拜占庭皇帝的妹妹安娜（Ἄννα）。编年史说，她带着神父和圣物渡过黑海，因离开故乡而哭泣。这桩婚姻为基辅带来了神父、圣像和书籍。第二年，基辅百姓在第聂伯河（Днѣпръ）中受洗，教会的新歌声开始在这片土地上响起。",

  // ——— Russians: siege … wedding ———
  "russians:siege": "1608年9月至1610年1月，在混乱时期（Смутное время），圣谢尔盖圣三一修道院（Троице-Сергиева лавра）遭到数万大军围困。院内有修士、一小支守军，以及数千名逃难来的农民。坏血病夺去的性命比大炮还多；修士们每天埋葬死者，钟声始终不断。挖地道的人截断了敌人挖到城墙下的坑道。十六个月后，围攻者撤走了，钟声为喜悦而鸣响。",
  "russians:triumph": "想象：春天，奥卡河（Ока）边的一个村庄。服役多年的士兵们背着行囊，沿着泥泞的道路走回家来。钟楼上有人望见了他们，钟声响起。妇女们捧着放在绣花毛巾上的面包和盐（хлеб да соль）跑出来；母亲们找到儿子，喜极而号。当晚，木屋（изба）里响起手风琴（гармонь），老人们为生者和死者举杯，众人一直唱到天亮。",
  "russians:build": "1714年，在奥涅加湖（Онежское озеро）的基日岛（Кижи）上，木匠们建起了主显圣容教堂（Преображенская церковь），二十二个木制圆顶直插云天，全凭斧头建成。传说工匠师傅涅斯托尔（Нестор）完工后把斧头扔进湖里，说：「从前没有这样的，现在没有，将来也不会有。」周围村庄的农民在冬天沿着冰面拖运原木，一边拉一边唱歌。",
  "russians:voyage": "几百年来，白海（Белое море）沿岸的波莫尔人（Поморы）驾驶一种叫科赫船（кочи）的小木船北上，到他们称为格鲁曼特（Грумант）的斯瓦尔巴群岛猎捕海象和海豹。这种船的船体是圆的，冰块挤压时会把船往上推，而不会把它压碎。有些船员在那里一住好几年。当积雪的山峰终于从雾中升起时，老船长画了个十字，年轻人欢呼起来。",
  "russians:festival": "1700年1月1日，奉彼得大帝（Пётр Великий）之命，俄罗斯人第一次在一月过新年；在此之前，一年从9月1日开始。人们被要求在大门上挂冷杉和松树枝，鸣枪、点篝火，莫斯科（Москва）的红场（Красная площадь）上空连续几天燃放烟火。有些老人嘟嘟囔囔，孩子们却很喜欢，那些冷杉枝后来就成了新年树（ёлка）。",
  "russians:games": "在村子里，俄罗斯人玩一种叫「戈罗德基」（городки）的游戏：在地上画一个方框，叫作「城」，在里面用五根木柱摆出各种图形，名字有「大炮」「星星」「信」等。玩家从远处投出一根沉重的木棒，把图形打出方框。农民、士兵、学童和老人都玩。夏日傍晚，木棒的撞击声在村子里回荡。",
  "russians:drought": "1891年，干旱和早霜毁掉了整个伏尔加（Волга）地区的收成，饥荒蔓延到十几个省。几十万人死于饥饿和随后的霍乱。列夫·托尔斯泰（Лев Толстой）和他的女儿们来到梁赞（Рязань）省的村庄，开办免费食堂，每天供养数千人。在寒冷的农舍里，农民一家吃着藜草（лебеда）做的面包，等待春天。",
  "russians:winter": "想象：1601年的冬天是大饥荒（Великий голод）的开端。八月就下了霜，冻死了田里的庄稼；夏天竟然下起了雪。接下来的几个冬天，人们吃稻草、树皮和野草，狼群闯进了村庄。农民们徒步前往莫斯科（Москва），因为沙皇在那里发放面包，许多人死在了半路的雪地里。教堂里，神父们日复一日诵读哀歌诗篇。",
  "russians:plague": "1771年，莫斯科（Москва）爆发瘟疫。最严重的时候，每天有上千人死去。城市被隔离，澡堂关闭，穿着浸过焦油衣服的囚犯用大车把尸体运出城外。绝望的人群聚集在瓦尔瓦尔卡（Варварка）城门的圣母像前；大主教想把圣像移走以防人群聚集，结果引发了暴动。直到霜冻降临，疫情才告结束。",
  "russians:wedding": "在俄罗斯乡村婚礼（свадьба）上，新娘要唱哭嫁歌（причитания），哀叹失去少女时光，告别娘家。婚礼前夜，女伴们解开她象征少女身份的单辫；从教堂回来后，已婚妇女们把她的头发编成两条辫子，再戴上科科什尼克头饰（кокошник）。宾客们分食卡拉瓦伊（каравай）——一个装饰着面团小鸟的大圆婚礼面包。随后手风琴（гармонь）奏响，众人翩翩起舞。",

  // ——— Magyars: siege … wedding ———
  "magyars:siege": "1532年8月，一支向维也纳（Wien）进军的庞大奥斯曼军队在小城克塞格（Kőszeg）停了下来。守城队长尤里希奇·米克洛什（Jurisics Miklós）手下不到一千人，大多是农民和市民。三个多星期里，他们打退了十九次进攻，夜里修补城墙。眼看城池将破之际，围攻者却突然撤走了。克塞格的教堂钟声至今每天上午十一点敲响，纪念敌军撤离的那个时刻。",
  "magyars:triumph": "1456年7月，匈雅提·亚诺什（Hunyadi János）率领的匈牙利军队和修士卡皮斯特拉诺的约翰（Giovanni da Capestrano）召集的十字军，为多瑙河（Duna）畔的南多尔白堡（Nándorfehérvár）解除了奥斯曼大军的围困。教皇加里斯都三世曾下令正午敲响教堂钟声，号召信众为守军祈祷。胜利的消息传来后，正午钟声便成了感恩之钟，响遍整个基督教世界。在每一座马扎尔城镇，人们都在教堂里高唱《赞美颂》（Te Deum）。",
  "magyars:build": "1241年蒙古入侵摧毁了匈牙利大部分土木要塞，此后国王贝拉四世（IV. Béla）号召一切有能力的人用石头建造城堡。在随后的几十年里，修士、领主和市民在全国各地的山顶上建起了城堡。不妨想象一个村庄正在修筑城墙：石匠叮当敲打，妇女用篮子背着石灰，一位风笛手（duda）吹奏着，男人们抬起梁木。他们见过草原燃烧，绝不愿再见到第二次。",
  "magyars:voyage": "约895年，阿尔帕德（Árpád）率领马扎尔七部落经维雷茨凯山口（Vereckei-hágó）翻越喀尔巴阡山（Kárpátok），进入多瑙河（Duna）与蒂萨河之间的广阔盆地。他们经历了从东方而来的漫长迁徙，带着家眷、畜群和车辆。编年史说，他们找到了一片水草丰美的土地。马扎尔人称之为「honfoglalás」，意为占据家园，平原在他们脚下展开的那一刻，被写进了许多歌谣。",
  "magyars:festival": "在圣诞节和新年之间，马扎尔青年结伴挨家挨户进行「雷戈什歌唱」（regölés）。他们拿着带铁链、摇起来哗哗作响的手杖和用陶罐做成的摩擦鼓（köcsögduda），唱着副歌为「haj regő rejtem」的古老歌谣，祝愿主人家富足：羊羔多得像天上的星星，女儿嫁个好丈夫。作为回报，他们得到香肠、糕点和葡萄酒，那些异教时代的词句就这样流传了好几个世纪。",
  "magyars:games": "想象：十世纪的草原上。年轻的马扎尔骑手在夏季营地比武：他们策马飞驰掠过靶子，回身越过马尾向后射箭，这就是著名的「安息回马箭」；他们还摔跤、赛马、套捕野马驹。老人们在一旁观看，回想起自己的青春。最好的弓手从首领手中得到一张良弓，科博兹琴（koboz）琴手在晚间的篝火旁歌唱他的名字。",
  "magyars:drought": "1863年，一场严重的旱灾袭击了匈牙利大平原（Alföld）。几个月滴雨未下；水井干涸，青草枯黄，牛群成千上万地死去。农民们吃麸皮和草根，许多人把牲畜几乎白送着卖掉。国内外的救济委员会把粮食送到各个村庄。在平原的歌谣里，这一年被记作「大旱之年」，连青蛙都不再鸣叫。",
  "magyars:quake": "1763年6月28日，一场强烈地震袭击了多瑙河（Duna）畔的科马罗姆（Komárom）。教堂和房屋倒塌，数十人遇难；余震持续不断，更多人逃到田野里，在帐篷中住了好几个星期。为感谢幸存，市民们立起了一根圣三一（Szentháromság）纪念柱，还建了一座圣母教堂。很长一段时间里，人们都说科马罗姆的大地每逢暴风雨就会颤抖。",
  "magyars:winter": "想象：普斯塔草原（puszta）上的暴风雪。狂风在一望无际的平原上呼啸了三天，没有任何东西能挡住它；积雪堆得有一人高。牧羊人（juhászok）把羊群赶进芦苇棚，披着厚重的苏尔斗篷（szűr）轮流守夜、轮流睡觉。有些羊就那样站着冻死了。风暴过后，牧羊人在白茫茫的寂静中吹起竖笛（furulya），牧羊犬把走失的羊羔从雪里刨出来。",
  "magyars:plague": "想象：1739年，瘟疫沿多瑙河（Duna）而上，传到大平原（Alföld）的城镇。塞格德（Szeged）的议会关闭了城门，在十字路口焚烧稻草来净化空气。整条整条的街道被木板封住，大车在夜里收运死者。瘟疫过去后，塞格德人和许多匈牙利城镇一样，立起一根圣三一（Szentháromság）瘟疫纪念柱，聚集在那里唱一首感恩赞美诗。",
  "magyars:wedding": "在匈牙利乡村婚礼（lakodalom）上，司仪（vőfély）手持饰有缎带的手杖，每上一道菜都要念一段顺口溜：汤、酿白菜卷、糕点。午夜时分是新娘之舞（menyasszonytánc）：每位宾客都要付钱和新娘跳一轮，把硬币投进盘子里，最后由新郎把她「赎」回来。罗姆乐队（cigányzenekar）和扬琴（cimbalom）乐手的演奏一直持续到天亮。",

  // ——— Bulgarians: siege … wedding ———
  "bulgarians:siege": "1393年，奥斯曼军队围攻了特尔诺沃（Търново），这座都城坐落在扬特拉河（Янтра）上方的岩石山丘上。人们坚守了三个月。牧首叶夫蒂米（Евтимий）是一位曾修订教会典籍的学者，他带领市民守城，并在城墙上与他们一同祈祷。7月17日，城市陷落。牧首被流放，他的弟子们把他的书带到其他斯拉夫国度的修道院，他的著作在那里流传了下来。",
  "bulgarians:triumph": "想象：一场漫长的征战之后，男人们翻越巴尔干山脉，即老山（Стара планина），回到家乡。村里的教堂钟声响起，妇女们穿上最好的绣花衬衫走出门来。风笛（гайда）吹响，塔潘鼓（тъпан）隆隆作响，全村人手拉手，在广场上跳起链舞「霍罗」（хоро）。人们掰开面包，斟满美酒；最后，大家轻声唱出那些没能回来的人的名字。",
  "bulgarians:build": "一首巴尔干叙事歌讲述了曼诺尔师傅（майстор Манол）和他的工匠们的故事：他们怎么也建不成一座桥（也有说是一座修道院），因为每天夜里墙都会倒塌。一个梦告诉他们，第二天第一个给丈夫送午饭来的妻子，必须被砌进地基里。第一个来的是曼诺尔年轻的妻子。他们一边唱歌一边把她砌进墙里，她哀求他们留一个洞，好让她给孩子喂奶。墙立住了，而她的乳汁至今仍在流淌。",
  "bulgarians:voyage": "约680年，保加尔可汗阿斯帕鲁赫（Аспарух）率领族人离开草原，沿黑海海岸向西，渡过多瑙河（Дунав）。他们带着马匹、家眷和毡帐，来到大河与巴尔干山脉之间的土地，那里早已住着斯拉夫农民。在那里，两个民族共同融合为一体。编年史说，阿斯帕鲁赫的族人定居在普利斯卡（Плиска）附近，而那次渡河正是一个新家园的开端。",
  "bulgarians:festival": "冬天，保加利亚的村庄里会出现「库克里」（кукери）。男人们戴着木头和毛皮做的巨大面具，上面有角、镜子和彩色流苏，腰带上挂着沉重的铜铃，他们在街上跳跃舞动，让铃铛叮当作响。这喧闹声是为了驱赶恶灵，唤醒大地迎接春天。孩子们躲起来尖叫，老妇人们在每家门口给库克里送上面包和葡萄酒。",
  "bulgarians:games": "在乡村集市上，保加利亚摔跤手（пехливани）穿着皮马裤在草地上比赛，身上抹了油，让对手抓不住。每场比赛之前，摔跤手们并肩走动，弯腰触摸地面，苏尔奈管（зурна）和塔潘鼓（тъпан）奏起一支缓慢的曲子，比赛一开始节奏就加快。人群呐喊着，为本村的选手下注。赢家得到一头公羊，被人扛在肩上绕着草地游行。",
  "bulgarians:drought": "在保加利亚的村庄里，夏天干旱时，姑娘们会举行「佩佩鲁达」（пеперуда）仪式，意思是蝴蝶。一个小女孩，常常是孤儿，全身只裹着树叶和藤蔓。她挨家挨户跳舞，女伴们唱着「蝴蝶飞呀飞，求上天降雨」；每到一家，女主人就往她身上泼水，并送给姑娘们面粉或鸡蛋。老人们望着天空，等待云来。",
  "bulgarians:quake": "1928年4月14日和18日，两次强烈地震袭击了色雷斯（Тракия）平原的奇尔潘（Чирпан）和普罗夫迪夫（Пловдив）一带。数千座房屋倒塌，奇尔潘几乎全城被毁。家家户户睡在户外的帐篷和大车里，在春雨中生火做饭，士兵和志愿者则在废墟中挖掘。援助从全国各地赶来，几年之内城镇就得到了重建。",
  "bulgarians:winter": "想象：罗多彼山（Родопи）高处的冬天。大雪封住村与村之间的小路，一封就是好几个星期。牧羊人把羊群赶下山，关进石砌的畜棚，一家人聚在火炉旁。晚上，妇女们在织机前干活，男人们吹起低沉的罗多彼大风笛（каба гайда），笛声在黑暗中回荡。平安夜，男孩们组成报佳音的队伍（коледари），踏着积雪挨家挨户唱颂歌。",
  "bulgarians:plague": "想象：1837年夏天，瘟疫传到索非亚（София）附近的村庄。一家家人逃进山里，病人被留在村外的小屋中，食物和水放在远处。神父捧着圣像绕村行走，在村子边缘洒圣水；老妇人们按祖母传下的办法，用一对孪生牛拉犁，绕着房屋犁出一道护身的犁沟。",
  "bulgarians:wedding": "保加利亚的乡村婚礼（сватба）要持续好几天。星期五，妇女们揉制婚礼面包，新郎的朋友们竖起婚礼旗——一根顶端插着苹果、挂满缎带的旗杆。星期日，新娘蒙着红色面纱，向父母告别，亲吻他们的手。主婚的教父（кум）主持仪式，风笛和塔潘鼓一路吹打到教堂。",

  // ——— Byzantine Greek: siege … wedding ———
  "byzantines:siege": "约586年，以及后来的610年代，阿瓦尔人和斯拉夫人两度围攻塞萨洛尼基（Θεσσαλονίκη）。由该城历任大主教撰写的《圣德米特里奥斯（Ἅγιος Δημήτριος）奇迹录》讲述了城中饥荒严重、守军寡少的困境，但市民们看见一位身披白斗篷的士兵沿着城墙奔跑，击倒来犯之敌。他们认得他：那正是他们的守护圣人德米特里奥斯。城市守住了，此后塞萨洛尼基人每年10月26日都庆祝他的节日。",
  "byzantines:triumph": "629年，经过与波斯六年的战争，皇帝希拉克略（Ἡράκλειος）回到君士坦丁堡（Κωνσταντινούπολις）。人们渡过博斯普鲁斯海峡（Βόσπορος），手持橄榄枝和蜡烛到希耶里亚（Ἱέρεια）迎接他，唱着圣歌，喜极而泣。他穿城而过的凯旋行列中有四头大象，那是城里人从未见过的。第二年，他徒步把从波斯人手中夺回的真十字架（Τίμιος Σταυρός）送回耶路撒冷（Ἱεροσόλυμα），钟声和圣咏迎接着它。",
  "byzantines:build": "963年，修士阿塔纳修斯（Ἀθανάσιος）创建了大拉夫拉修道院（Μεγίστη Λαύρα），这是阿索斯圣山（Ἄθως）上第一座大修道院。修士和工匠们从海边把石头运上山，建起一座带圆顶的教堂和一座摆着长条大理石桌的食堂，又在陡峭的山坡上种下葡萄和橄榄。阿塔纳修斯和他们一起劳动；据说1004年，他在视察一座圆顶时圆顶坍塌，他因此去世。他的修士们完成了这项工程。",
  "byzantines:voyage": "据普罗科匹厄斯（Προκόπιος）记载，约552年，几位修士来见皇帝查士丁尼（Ἰουστινιανός），答应为他带回只有中国人知道的养蚕秘密。他们前往一个希腊人称为塞林达（Σήρινδα）的遥远国度，回程时把蚕卵藏在空心手杖里。穿越亚洲的漫长旅途之后，他们抵达君士坦丁堡（Κωνσταντινούπολις），蚕卵在桑叶上孵化了。此后数百年，拜占庭希腊人一直自己生产丝绸。",
  "byzantines:festival": "想象：色萨利（Θεσσαλία）一个拜占庭村庄的守护圣人节，即庙会（πανήγυρις）。早晨的礼拜结束后，整个山谷的人都聚到教堂旁的草地上。商人们摆开布匹、陶罐和蜂蜜；杂耍艺人表演；里拉琴（λύρα）和双管笛（aulos）奏响，年轻人连成一条长链跳舞。各家烤起羔羊，老朋友们一年来第一次相聚。集市一直持续到满天星斗。",
  "byzantines:games": "波菲里乌斯（Πορφύριος）是六世纪君士坦丁堡最伟大的战车御者。他曾先后为蓝党（Βένετοι）和绿党（Πράσινοι）驾车，屡战屡胜，以至于城市在赛马场（Ἱππόδρομος）为他立了至少七座雕像，这种荣誉通常只给皇帝。这些雕像的基座至今尚存，上面刻着赞美他技艺的诗句，描述他高扬马鞭冲过终点时，观众如何高声呼喊他的名字。",
  "byzantines:drought": "想象：小亚细亚一个干旱的夏天。雨水迟迟不来，麦田一片枯黄，主教率领一支祈雨游行队伍（λιτή）走出城去。神父们抬着圣像和圣物，人们赤着脚，一遍又一遍地唱着「Kyrie eleison」（Κύριε ἐλέησον），主啊，怜悯我们。孩子们手持橄榄枝。到了山上的小教堂，他们跪下等待。天空依旧湛蓝，但第二天他们又来了。",
  "byzantines:quake": "526年5月29日，正值耶稣升天节，一场大地震袭击了安条克（Ἀντιόχεια）。这是帝国最大的城市之一，当时挤满了朝圣者。建筑倒塌，大火在废墟中蔓延了好几天。编年史家说，有二十五万人丧生，其中包括牧首。幸存者聚集在山上祈祷。城市重建后改名为塞奥波利斯（Θεούπολις），意为「上帝之城」，寄望于更好的日子。",
  "byzantines:winter": "想象：卡帕多西亚（Καππαδοκία）的一个严冬。大雪覆盖了高原，也覆盖了凿在软岩中的洞穴村落。人们和牲畜一起待在温暖的岩屋里，炉火的烟从崖壁间袅袅飘出。在油灯照亮的洞穴教堂里，修士们吟唱夜课经，壁画上的圣徒俯视着他们。面包按量分配，到了圣诞节，大家分享剩下的最好的东西。",
  "byzantines:plague": "1347年，黑死病从黑海港口传到君士坦丁堡（Κωνσταντινούπολις）。皇帝约翰六世·坎塔库泽努斯（Καντακουζηνός）自己年幼的儿子安德罗尼库斯（Ἀνδρόνικος）也死于此病，他写道，这场疾病不放过任何人，无论贫富；许多人看到别人死去，便忏悔并散尽家财。他写道，什么都没用，医生没用，祈祷也没用。拜占庭希腊人用古老的哀歌安葬死者，城市变得越来越空。",
  "byzantines:wedding": "在拜占庭婚礼中，加冕礼（στεφάνωμα）是仪式的核心，今天的希腊东正教婚礼依然如此。神父把用鲜花或金属制成、以缎带相连的婚冠（στέφανα）戴在新娘和新郎头上，伴郎将婚冠交换三次。新人共饮一杯，在唱诗班的歌声中绕桌三圈。接着便是宴席，有音乐，也有舞蹈。",

  // ——— Constantinople: siege … wedding ———
  "macedonian-dynasty:siege": "从717年夏天到718年8月，一支庞大的阿拉伯军队和舰队围攻君士坦丁堡（Κωνσταντινούπολις）。城市守住了陆墙，敌方舰队被希腊火焚毁。随后是一个可怕的冬天：积雪在地上留了一百天，城外的围攻者饥寒交迫。城内的人们祈祷着，按量分配粮食。围攻者终于撤退时，一场风暴又摧毁了他们剩下的船只。",
  "macedonian-dynasty:triumph": "971年，在多瑙河畔的长期战争之后，皇帝约翰·齐米斯基斯（Τζιμισκῆς）凯旋回到君士坦丁堡（Κωνσταντινούπολις）。市民们用花环和地毯装点街道。一辆由白马拉着的金色战车在等着他，但他不肯坐上去，而是把从普雷斯拉夫（Прѣславъ）带回的圣母（Θεοτόκος）像安放在车上，自己骑马跟在后面，把胜利的荣耀归于圣母。",
  "macedonian-dynasty:build": "圣索菲亚大教堂（Ἁγία Σοφία）在数学家特拉勒斯的安特米乌斯（Ἀνθέμιος ὁ Τραλλιανός）和米利都的伊西多尔（Ἰσίδωρος ὁ Μιλήσιος）主持下，由一万名工人用不到六年时间建成，从532年到537年。普罗科匹厄斯（Προκόπιος）说，圆顶升起时，仿佛是用一条金链从天上悬挂下来的。537年12月27日，皇帝查士丁尼（Ἰουστινιανός）走进落成的教堂，相传他高呼：「所罗门，我胜过你了！」（Νενίκηκά σε, Σολομών!）数百年来，圣咏一直在那座圆顶下回响。",
  "macedonian-dynasty:voyage": "想象：每年夏天，运粮船从埃及向北航行，为君士坦丁堡（Κωνσταντινούπολις）运送粮食。每次航行都要在开阔的海上走好几个星期，经过罗得岛（Ῥόδος），穿越赫勒斯滂海峡（Ἑλλήσποντος），顶着风浪和逆流前进。终于在一个日出时分，水手们望见了那座城的圆顶和城墙在山丘上闪闪发光。他们唱起献给圣母的赞美诗；港口里，码头工人们挥手呼喊，迎接粮食上岸。",
  "macedonian-dynasty:festival": "每年5月11日，君士坦丁堡（Κωνσταντινούπολις）都要庆祝自己的生日，纪念330年君士坦丁（Κωνσταντῖνος）为这座城市举行奉献典礼的那一天。赛马场（Ἱππόδρομος）里举行战车比赛，一尊镀金的君士坦丁像被放在车上绕跑道巡行，雕像手中托着象征城市命运的小小堤喀（Τύχη）女神像，士兵们手持蜡烛相随。皇帝起身向雕像鞠躬。民众高唱颂词，节庆一直持续到深夜。",
  "macedonian-dynasty:games": "在君士坦丁堡（Κωνσταντινούπολις）的宫苑里，巴西尔一世（Βασίλειος Αʹ）重修了「齐卡尼昂」（τζυκάνιον）球场，这是一种从波斯传来的马球。骑手们手持末端带网的长杆，在草地上追逐一只皮球。年轻的皇帝们都很喜爱这项运动。编年史说，913年皇帝亚历山大（Ἀλέξανδρος）在一个炎热的日子打完马球后病倒，随即去世。宫廷众人在阳台上观看，场外的人群则倾听着马蹄声。",
  "macedonian-dynasty:drought": "想象：君士坦丁堡（Κωνσταντινούπολις）一个滴雨未下的夏天。瓦伦斯水道桥的水流越来越细，人们拿着水罐和水桶，在城下的大蓄水池前排起长队。在地下水宫（Βασιλικὴ Κινστέρνα）拱顶下的黑暗中，水位一根柱子接一根柱子地下降。牧首带领队伍抬着圣物绕城墙游行，吟唱连祷文，城里的面包师们为面粉价格争吵不休。所有人都在望着天空。",
  "macedonian-dynasty:quake": "557年12月，一场大地震使君士坦丁堡（Κωνσταντινούπολις）连续震动了好几天。房屋和教堂倒塌，圣索菲亚大教堂（Ἁγία Σοφία）的圆顶也出现了裂缝。558年5月，工人们正在修缮时，圆顶东半部坍塌，砸毁了祭坛。人们在街头哭泣。小伊西多尔（Ἰσίδωρος ὁ νεώτερος）把圆顶重建得更高、更陡，562年教堂再次举行奉献典礼，人们第一次唱起了为此谱写的赞美诗。",
  "macedonian-dynasty:winter": "编年史家塞奥法尼斯（Θεοφάνης）记载，763年至764年的冬天冷得出奇，黑海从海岸向外冻结了一百英里。二月解冻时，巨大的冰山顺着博斯普鲁斯海峡（Βόσπορος）漂流而下，堆积在君士坦丁堡（Κωνσταντινούπολις）的海墙下。人们踩着冰从一岸走到另一岸。塞奥法尼斯那时还是个孩子，和三十个小伙伴一起到冰上玩耍。",
  "macedonian-dynasty:plague": "542年，瘟疫从海上传到君士坦丁堡（Κωνσταντινούπολις）。亲眼目睹的普罗科匹厄斯（Προκόπιος）写道，最严重时每天有一万人死去。坟墓不够用了，死者被堆进城墙的塔楼里，臭气弥漫全城。商铺关门，皇帝也染病后又痊愈，人们在胳膊上系上名牌，以便死在街头时能被认出来。",
  "macedonian-dynasty:wedding": "约830年，皇帝塞奥菲洛斯（Θεόφιλος）举行了一场选妃会。帝国最美丽的姑娘们站成一排，他手持一只金苹果，准备送给自己选中的人。他在卡西娅（Κασσιανή）面前停下，说：「罪恶是通过女人来到世上的。」她回答：「但更美好的也是通过女人而来。」皇帝觉得受了冒犯，把苹果给了塞奥多拉（Θεοδώρα）。卡西娅后来成为修女，也是拜占庭最伟大的赞美诗作者之一。",
  "goths:showcase": "哥特人（Gutþiuda, 𐌲𐌿𐍄𐌸𐌹𐌿𐌳𐌰）没有留下任何乐谱，所以这首乐曲是根据零星线索重构的。历史学家约达尼斯写道，他们伴着曲调和里拉琴歌唱祖先的事迹；罗马作家则描述过「巴里图斯」（barritus），一种从低语逐渐膨胀为怒吼的战吼。特罗辛根和萨顿胡等日耳曼墓葬中保存了圆形木制里拉琴，骨笛和兽角在整个北方都是常见的出土物。乌尔菲拉为族人译出哥特文圣经后，他们开始唱基督教赞美诗；在西哥特时期的西班牙，后来被称为古西班牙圣咏的教会歌咏逐渐成形，它所用的纽姆谱至今仍无法完全解读。这里由里拉琴领奏，配以骨笛、角笛持续音、原牛角号和框鼓。",
  "teutons:showcase": "条顿骑士团（Deutscher Orden）于1190年代创立于阿卡，不久便派骑士前往波罗的海，把德语地区拉丁基督教世界的音乐带到了北方。修士们的日常按照格里高利圣咏的时辰进行，其中有献给圣母玛利亚的特别赞美诗。同一时代，恋诗歌（Minnesang）盛行：瓦尔特·冯·德·福格尔魏德（Walther von der Vogelweide）等诗人歌手伴着菲德尔琴（vielle）歌唱，他的《巴勒斯坦之歌》（Palästinalied）是少数旋律得以留存的十字军歌曲之一。当时的图画和文献中还有鲁特琴、竖琴、笛子与小鼓、便携式管风琴、长柄布辛号（busine），以及在东方遇见的小型定音鼓（nakers）。如今，古乐团依据手稿和图像重建这种声音；这里由菲德尔琴领奏，鲁特琴和便携式管风琴伴奏。",
  "germans:showcase": "施瓦本汝拉山洞穴中出土的鸟骨笛和猛犸象牙笛约有四万年历史，是已知最古老的乐器之一。中世纪有恋诗歌手，后来有城市中的工匠歌手（Meistersinger），如纽伦堡的汉斯·萨克斯（Hans Sachs），他们演唱分节歌曲；16世纪的雇佣兵（Landsknecht）则伴着施韦格尔横笛（Schwegel）和长鼓行军。马丁·路德的众赞歌让会众有了德语赞美诗，由教堂唱诗班（Kantorei）演唱、宏伟的教堂管风琴伴奏，这一脉络一直延续到巴赫。维奥尔琴合奏（Gamben）、哈克布雷特扬琴（Hackbrett）、竖笛（Blockflöte）、定音鼓和圆号（Waldhorn）充盈于宫廷和城镇，18世纪的乐队还借用了土耳其大鼓和钹。长号合唱团（Posaunenchor）、教堂管风琴和阿尔卑斯齐特琴至今仍广为演奏。",
  "holy-roman-empire:showcase": "在莱茵河（Rhein）沿岸，书面记载的音乐始于教会。查理曼的礼拜堂设在亚琛，在他治下，法兰克领唱者推广了格里高利圣咏；757年拜占庭送给法兰克国王的一架管风琴，又把这件乐器带回了西方。《音乐手册》（Musica enchiriadis）等早期论著描述了奥尔加农（organum），即以平行五度和四度进行的多声部歌唱。12世纪，宾根的希尔德加德（Hildegard von Bingen）创作了高扬飞升的圣咏和歌剧式的《美德之序》（Ordo Virtutum），这是中世纪有名可考的作曲家留下的最大圣咏作品集之一。后来，大教堂和城市乐师又加入了索尔特里琴、竖笛、菲德尔琴、木管号（Zink）和萨克布特长号（Posaune），典礼上还有小号和定音鼓。科隆、美因茨和施派尔至今仍回荡着大教堂唱诗班、管风琴和大钟的声音，希尔德加德的音乐也重新被人传唱。",
  "order-of-the-dragon:showcase": "特兰西瓦尼亚（Erdély, Siebenbürgen, Ardeal）长久以来是匈牙利、罗马尼亚和萨克森歌谣交汇之地。中世纪文献显示，拉丁欧洲的乐器陆续传入：贵族和城市使用的布辛号、手摇弦琴（tekerőlant）、菲德尔琴，以及修道院的圣咏。萨克森村民建起了设防教堂，许多教堂至今仍保存着历史悠久的管风琴；这里的便携式管风琴就代表着这一传统。牧人吹奏弗卢亚笛（furulya），东部则用短颈鲁特琴科博兹（koboz）为歌唱伴奏。18世纪起，由小提琴、和弦中提琴（kontra）和低音提琴组成的乡村弦乐队主导着婚礼和舞会；1907年起，巴托克·贝拉（Bartók Béla）开始收集这一地区的歌谣。自1970年代以来，舞蹈屋（táncház）运动让这些乡村风格在新一代演奏者中复兴。",
  "vikings:showcase": "诺尔斯人（Norrǿnir）的音乐从未被记录下来，所以这首乐曲是根据出土文物和文献记述重构的。墓葬和聚落遗址中出土了拨弦里拉琴的部件、骨笛、牛角号和木制卢尔号（lúðr），约克的科珀盖特还挖出了一套10世纪的黄杨木排箫。吟唱诗人在宴会上朗诵结构繁复的诗篇；一位来自安达卢斯的旅行者图尔图希（الطرطوشي）则嘲笑他在海泽比听到的歌声比狗叫还难听。皈依基督教后，拉丁圣咏随教会传入北方。更古老的歌唱方式在冰岛的里穆尔（rímur）吟诵、双声部歌唱（tvísöngur）和挪威的克韦丁（kveding）中延续下来。如今，乐手们根据出土残件重建里拉琴、笛子和号角，正如这里所听到的。",
  "swedes:showcase": "中世纪叙事歌谣在瑞典人（Svenskar）的村庄里广为传唱；键弦提琴尼古尔哈帕（nyckelharpa）最早的图像，刻在约1350年哥特兰岛卡隆格教堂的门廊上。路德宗改革带来了会众齐唱的赞美诗和教堂管风琴。17世纪起小提琴（fiol）流行开来，波尔斯卡（polska）这种节拍轻快而不均匀的三拍子舞曲，成了提琴手曲目的核心。在夏季牧场上，牧人用「库尔宁」（kulning）呼唤牲畜，吹奏牧角（vallhorn）和桦树皮长号（näverlur）；家中则有风笛（säckpipa）、斯佩尔笛（spelpipa）和胡默尔齐特琴（hummel）。自20世纪初的提琴手聚会（spelmansstämmor）和现代半音尼古尔哈帕出现以来，这些传统一直保持着旺盛的生命力，尤以乌普兰为甚。",
  "lithuanians:showcase": "立陶宛人（Lietuviai）直到14世纪末仍保持着古老的宗教，他们的音乐也大多扎根于乡村仪式。坎克勒琴（kanklės）是一种翼形拨弦索尔特里琴，与拉脱维亚的科克勒琴（kokle）和芬兰的康特勒琴（kantele）同属古老的波罗的—芬兰乐器家族。在东北部的奥克什泰蒂亚（Aukštaitija），妇女们演唱「苏塔尔蒂内斯」（sutartinės）：短小交错的卡农，声部之间以二度相撞。男人们则用由数人分吹的排箫斯库杜恰伊（skudučiai）和长木号道迪特（daudytė）演奏同样的复调。风笛（dūdmaišis）、伦兹德利斯笛（lumzdelis）、号角和鼓服务于婚礼和农事年历。苏塔尔蒂内斯在20世纪几近消失，但经过录音和复兴保存了下来，坎克勒琴合奏如今也广为流行。",
  "poles:showcase": "波兰人（Polacy）的歌曲最早以《圣母颂》（Bogurodzica）见诸文字，这是骑士们在战前唱的献给圣母的赞美诗，15世纪连同旋律一起被抄录下来。长久以来，克拉科夫圣玛利亚教堂的塔楼上都有号手吹奏「海伊纳乌」（hejnał）号曲，如今每小时一次。格但斯克的考古发掘出土了格希莱琴（gęśle），一种中世纪小提琴；而苏卡琴（suka）是一种用指甲按弦的膝上提琴，在比乌戈拉伊地区留有记忆，并在现代得到重建。文艺复兴时期的鲁特琴师把波兰舞曲传遍欧洲，由小提琴、巴西低音琴（basy）、钦巴维扬琴（cymbały）和山羊风笛（koza）组成的乡村乐队（kapela）演奏玛祖卡。肖邦把玛祖卡带进了音乐厅，塔特拉山区古拉尔人（Góral）的提琴手、特龙比塔长号（trombita）和富雅尔卡笛（fujarka）至今仍在演奏。",
  "bohemians:showcase": "最古老的捷克歌曲《主啊，怜悯我们》（Hospodine, pomiluj ny）和献给圣瓦茨拉夫的众赞歌（Svatý Václave）都出自中世纪波希米亚人（Čechové）的教会。15世纪的胡斯派改革把用民众自己的语言歌唱置于礼拜的中心；《伊斯泰布尼采赞美诗集》保存了胡斯军队所唱的《你们这些上帝的战士》（Ktož jsú boží bojovníci）。乡村音乐中有杜迪风笛（dudy），这种风笛带有弯曲的号角形喇叭口，流行于霍德地区和斯特拉科尼采一带；此外还有豪斯莱提琴（housle）、民间低音提琴，摩拉维亚则有扬琴（cimbál）。18世纪，大批波希米亚音乐家在国外工作，这片土地因此被称为「欧洲的音乐学院」。后来斯美塔那引用了胡斯派众赞歌，杜迪风笛乐队至今仍在演奏。",
  "slavs:showcase": "关于早期斯拉夫人（Словѣне）的音乐，文字记载很少，但有一个故事格外突出：约591年，拜占庭历史学家塞奥菲拉克特·西莫卡塔讲述了三个被俘的斯拉夫人，他们身上没有武器，只带着里拉琴，并说自己的民族热爱音乐与和平。诺夫哥罗德的考古发掘出土了11世纪以后的木制古斯里琴（гусли），这种翼形索尔特里琴常刻有动物图案；早期文献还提到一种拉弦提琴斯梅克（smyk），后来称为古多克琴（гудок）。牧人吹奏双管笛斯维雷尔（свирель）和号角（rog），敲击木板克莱帕洛（klepalo）则用来召集众人。妇女们用敞开的嗓音演唱时令歌、婚礼歌和哀歌，承载着最古老的一层，其中许多歌曲连同古斯里琴和乡村笛子，至今仍在民间流传。",
  "rus:showcase": "988年皈依之后，罗斯（Русь）的教堂采用了拜占庭圣咏，并发展成兹纳缅尼圣咏（знаменный распев）：一种单声部旋律，用叫作「克留基」（крюки）的钩形符号记写。基辅圣索菲亚大教堂楼梯塔中的壁画描绘了11世纪的乐师和艺人；流浪艺人斯科莫罗赫（скоморохи）弹奏古斯里琴、古多克琴，吹奏笛子，直到17世纪遭到禁止。钟声自成一门艺术：钟不是摆动敲响，而是在巨大的报喜钟（blagovest）下奏出富有节奏的钟乐（звон）。15世纪末起，君主的歌唱书吏（pevchie dyaki）组成了宫廷合唱团；17世纪，多声部合唱从西方传入。旧礼仪派信徒至今仍按克留基演唱兹纳缅尼圣咏，敲钟人也让钟乐延续不绝。",
  "russians:showcase": "俄罗斯人（Русские）的民间乐器出人意料地很晚才定型。巴拉莱卡琴（балалайка）在17世纪末的文献中作为乡村和街头乐器出现；1880年代，瓦西里·安德烈耶夫把它改造成大小不一的系列，创建了由巴拉莱卡和多姆拉（домра）组成的乐团，多姆拉是一种圆形鲁特琴，得名于古代游吟艺人的一种乐器。加尔蒙手风琴（гармонь）在19世纪传遍乡村，随后又有了半音阶的巴扬（bayan）。更古老的层次依然存在：扎列伊卡簧管（zhaleika）、弗拉基米尔的牧人角号（rozhok）、18世纪那种每人只吹一个音的号角乐队、哥萨克男声合唱以及教堂钟声。格林卡和后来的作曲家都从这些歌曲中汲取素材，民间乐团和合唱团至今仍在演出。",
  "magyars:showcase": "匈牙利人（Magyarok）的民歌保留着非常古老的一层：下行的五声音阶曲调，把一个乐句在低五度上重复，柯达伊·佐尔坦（Kodály Zoltán）和巴托克·贝拉（Bartók Béla）把这种风格与伏尔加河沿岸各民族的歌曲联系起来。征服时代骑马民族的音乐此外再无记录，所以这首乐曲是用最接近的有据可查的乐器重构的。仲冬时节，雷戈什歌手挨家挨户唱着古老的祝福歌。牧人吹奏弗卢亚笛（furulya）和杜达风笛（duda），科博兹鲁特琴（koboz）和齐特拉琴（citera）为歌唱伴奏。16世纪，蒂诺迪·拉托什·谢拜斯蒂延（Tinódi Lantos Sebestyén）伴着鲁特琴吟唱编年史；18世纪出现了征兵舞曲（verbunkos）和带贝格低音提琴（bőgő）的提琴乐队，后来又加入了扬琴（cimbalom）。乡村乐手和舞蹈屋运动让这种音乐延续至今。",
  "bulgarians:showcase": "9世纪起，保加利亚人（Българи）就用斯拉夫语演唱礼拜仪式，当时西里尔和美多德的弟子，如奥赫里德的克雷芒，在他们中间传授教义，拜占庭圣咏塑造了他们的教会音乐；据说14世纪伟大的圣咏改革者约安·库库泽尔（Йоан Кукузел）的母亲就是保加利亚人。乡村音乐则走出了自己的路：牧人吹奏的斜吹卡瓦尔笛（кавал）、风笛（гайда）和罗多彼山低沉的大风笛（kaba gaida）、拉弦的加杜尔卡琴（гъдулка）和长颈坦布拉琴（tambura），配合7/8拍、11/8拍等不均匀节拍的舞蹈，乡村节庆上还有苏尔奈管和塔潘鼓。绍普地区的妇女以紧密的二声部和声歌唱，库克里假面人摇响沉重的铃铛。20世纪，菲利普·库特夫（Philip Koutev）的合唱团把这种歌声带到了全世界。",
  "byzantines:showcase": "拜占庭希腊人（Ῥωμαῖοι）继承了希腊的音乐理论和罗马世界的乐器，但他们最伟大的成就是宗教圣咏。6世纪，歌者罗曼诺斯（Ῥωμανὸς ὁ Μελῳδός）创作了长篇的吟唱布道诗「康塔基昂」（kontakia），后来的赞美诗作者把圣咏归纳为八种调式，即八调体系（Ὀκτώηχος）。纽姆记谱法从10世纪开始出现；14世纪，约安尼斯·库库泽利斯（Ἰωάννης Κουκουζέλης）把华丽的「美声」风格推向巅峰。在教堂之外，9世纪的地理学家伊本·胡尔达兹贝（ابن خرداذبه）指出拉弦的里拉琴（λύρα）是拜占庭乐器，管风琴、笛子、索尔特里琴、小号和定音鼓则服务于宫廷和军队。东正教堂里至今仍在持续低音（ison）之上演唱拜占庭圣咏，里拉琴也在克里特、本都和色雷斯延续着生命。",
  "macedonian-dynasty:showcase": "在君士坦丁堡（Κωνσταντινούπολις），音乐既标志着礼拜，也标志着典礼。在圣索菲亚大教堂的圆顶下，领唱者们演唱「大教堂」独有的歌唱日课；9世纪，修女卡西娅（Κασσιανή）写下的赞美诗至今仍在圣周传唱。君士坦丁七世的10世纪《典仪书》记载了赛车党派——蓝党和绿党（demes）——如何伴着管风琴向皇帝高唱颂词；在这里，管风琴是宫廷乐器，而非教堂乐器。来访的克雷莫纳的柳特普兰德描述过一座装有会唱歌的机械鸟的御座大殿。里拉琴、基萨拉琴、笛子、小号、定音鼓和木制敲板塞曼特隆（semantron）都在这座城市中奏响。它的拜占庭圣咏传遍整个东正教世界，城中的领唱者至今仍在演唱。",
});
